/* 자동 생성: node factory/gen-hub-locales.js — 직접 수정하지 마라. 진본은 js/locales.js (전 언어 카탈로그). */
window.I18N_LOCALES = window.I18N_LOCALES || {};
window.I18N_LOCALES["ko"] = {"_label":"한국어","tool.apy-calc.name":"APY 계산기","tool.apy-calc.use":"어떤 복리 주기에서든 APR을 APY로(또는 APY를 다시 APR로) 변환하고, 예금이 어떻게 늘어나는지 확인하며, 동일한 금리를 연 1회·월 복리·일 복리·연속 복리로 비교해 보세요.","tool.apy-calc.desc":"어떤 복리 주기에서든 APR을 APY로(또는 APY를 APR로) 변환하고, 금리를 나란히 비교하며, 예금 성장 예시까지 확인하세요. 무료이며 모든 계산은 브라우저에서 처리됩니다.","tool.blood-pressure-checker.name":"혈압 체커","tool.blood-pressure-checker.use":"수축기와 이완기 혈압을 입력하면 ACC/AHA 기준 혈압 단계를 바로 확인할 수 있습니다.","tool.blood-pressure-checker.desc":"수축기와 이완기 혈압을 입력하면 정상·주의·1단계·2단계·고혈압 위기까지 ACC/AHA 기준 혈압 단계를 전체 기준표와 함께 즉시 확인할 수 있습니다. 무료이며 모든 계산은 브라우저에서 처리됩니다.","tool.box-shadow-generator.name":"박스 섀도우 생성기","tool.box-shadow-generator.use":"슬라이더를 드래그해 오프셋, 블러, 스프레드, 색상을 조절하고 여러 그림자 레이어를 쌓은 뒤 완성된 box-shadow CSS를 바로 복사하세요.","tool.box-shadow-generator.desc":"슬라이더로 오프셋, 블러, 스프레드, 색상, 투명도를 조절하고 실시간 미리보기에서 최대 4개의 그림자 레이어를 쌓은 뒤 완성된 box-shadow CSS를 복사하세요. 모든 처리는 브라우저 안에서 이뤄집니다.","tool.break-even-calc.name":"손익분기점 계산기","tool.break-even-calc.use":"비용이 이기는 구간은 정확히 한 수량에서 끝납니다. 세 가지 숫자만 넣으세요.","tool.break-even-calc.desc":"고정비, 판매가, 단위당 변동비를 입력하면 손익분기 수량, 매출, 공헌이익을 계산합니다 — 선택적인 목표 이익 계산과 가격 민감도표도 함께 제공됩니다.","tool.calorie-deficit-calc.name":"칼로리 결핍 계산기","tool.calorie-deficit-calc.use":"체중을 감량하려면 하루에 칼로리를 얼마나 먹어야 할까요? 신체 정보와 주간 감량 속도를 입력하면 하루 칼로리 목표와 목표 체중까지의 예상 기간을 알 수 있습니다.","tool.calorie-deficit-calc.desc":"내 신체 정보와 주간 감량 속도를 입력하면 하루 칼로리 결핍 목표와 목표 체중까지의 예상 기간을 알 수 있습니다. 무료·광고 없음·브라우저에서 계산.","tool.circle-calc.name":"원 계산기","tool.circle-calc.use":"원의 반지름, 지름, 둘레, 넓이 중 아무거나 하나만 입력하세요 — 나머지 세 값이 즉시 채워지고, 사용된 공식이 아래에 표시됩니다.","tool.circle-calc.desc":"원의 반지름, 지름, 둘레, 넓이 중 하나만 입력하면 나머지 세 값을 공식과 함께 즉시 계산해줍니다. 무료이며 브라우저에서 바로 계산됩니다.","tool.credit-card-interest-calc.name":"신용카드 이자 계산기","tool.credit-card-interest-calc.use":"잔액과 연이율(APR)을 입력하면 지금 정확히 얼마의 이자를 내고 있는지 바로 확인할 수 있습니다. 이어서 최소결제 함정 시뮬레이터를 실행해 최소결제만 했을 때와 결제 금액을 고정했을 때, 완납까지 걸리는 기간과 총이자를 비교해보세요.","tool.credit-card-interest-calc.desc":"잔액과 연이율(APR)을 입력하면 오늘 발생하는 이자를 바로 확인할 수 있습니다. 이어서 최소결제 함정 시뮬레이터로 최소결제만 할 때와 고정 금액으로 갚을 때의 상환 기간·총이자를 비교해보세요. 무료, 브라우저에서만 계산됩니다.","tool.debt-payoff-calc.name":"빚 상환 계산기","tool.debt-payoff-calc.use":"예산은 하나, 상환 순서는 둘. 어느 쪽이 더 빨리 끝나고 그 차이가 얼마인지 확인하세요.","tool.debt-payoff-calc.desc":"잔액, 연이율(APR), 월 상환액을 입력하면 빚을 다 갚기까지 걸리는 개월 수, 총이자, 상환 완료일, 전체 상환 스케줄을 바로 볼 수 있습니다. 무료이며 모든 계산은 브라우저에서 실행됩니다.","tool.electricity-cost-calc.name":"전기요금 계산기","tool.electricity-cost-calc.use":"와트 × 시간 ÷ 1000, 여기에 kWh 단가를 곱하면 끝입니다. 가전 하나가 요금에 얼마를 더하는지 확인하세요.","tool.electricity-cost-calc.desc":"가전제품의 소비전력, kWh당 요금, 사용 시간을 입력하면 일/월/연 전기요금을 확인할 수 있습니다. 냉장고, 에어컨 등은 빠른 프리셋으로 추가하세요.","tool.fire-calc.name":"FIRE 계산기","tool.fire-calc.use":"4% 룰(또는 3~5% 사이 원하는 인출률)로 연 지출을 FIRE 넘버로 바꾸고, 저축과 투자를 이어갈 때 경제적 자유까지 몇 년이 남았는지 확인하세요 — 린/레귤러/팻 FIRE 비교까지 함께요. 어떤 통화로도 사용할 수 있습니다.","tool.fire-calc.desc":"4% 룰로 연 지출을 FIRE 넘버로 바꾸고, 경제적 자유까지 남은 기간과 목표 시점, 린/레귤러/팻 단계까지 확인하세요. 무료, 브라우저에서만 계산.","tool.margin-calc.name":"마진 계산기","tool.margin-calc.use":"마진은 이익÷판매가, 마크업은 이익÷원가입니다. 마진 40%는 마크업 66.7% — 이 둘을 섞는 순간 가격이 무너집니다.","tool.margin-calc.desc":"원가, 매출, 마진율, 마크업율 중 아무 두 값이나 입력하면 나머지와 이익이 즉시 계산되고, 헷갈리기 쉬운 마진율과 마크업율의 차이도 명확히 정리됩니다.","tool.markup-calc.name":"마크업 계산기","tool.markup-calc.use":"원가를 판매가로 바꾸거나, 이미 받고 있는 판매가로부터 마크업률과 마진율을 구해보세요 — 브라우저에서 바로, 즉시 계산됩니다.","tool.markup-calc.desc":"원가와 마크업 %로 판매가와 이익을, 원가와 판매가로 마크업 %와 마진율을 계산합니다. 무료·즉시 계산, 브라우저에서만 처리됩니다.","tool.meta-tag-generator.name":"메타태그 생성기","tool.meta-tag-generator.use":"페이지 정보를 입력하면 바로 붙여넣을 수 있는 <title>, 메타 설명, Open Graph, Twitter Card 태그가 완성됩니다 — 실시간 검색결과·소셜 공유 미리보기까지 함께.","tool.meta-tag-generator.desc":"title, description, canonical, robots, Open Graph, Twitter Card 태그를 폼 하나로 생성하고, 구글 검색·소셜 공유 미리보기까지 실시간으로 확인하세요.","tool.pythagorean-calc.name":"피타고라스 정리 계산기","tool.pythagorean-calc.use":"변 a, 변 b, 빗변 c 중 아무 두 변이나 입력하면 나머지 한 변이 풀이 과정, 넓이, 둘레와 함께 즉시 나타납니다.","tool.pythagorean-calc.desc":"직각삼각형의 두 변만 입력하면 a² + b² = c² 공식으로 나머지 한 변을 즉시 구합니다. 풀이 과정, 넓이, 둘레까지 표시. 무료이며 모든 계산은 브라우저에서 이루어집니다.","tool.ratio-calc.name":"비율 계산기","tool.ratio-calc.use":"비례식을 풀거나, 비율을 최소 정수비로 약분하거나, 비율을 확대·축소해 보세요 — 탭을 선택하고 숫자를 입력하면 바로 답이 나옵니다.","tool.ratio-calc.desc":"A:B = C:D에서 빈 값을 구하거나, 비율을 최소 정수비로 약분하거나, 비율에 배율을 곱해 확대·축소하세요. 무료, 즉시 계산, 모든 계산은 브라우저에서 실행됩니다.","tool.retirement-calc.name":"은퇴 저축 계산기","tool.retirement-calc.use":"내 401(k)가 은퇴 때 얼마가 될지, 그중 회사가 넣어준 돈은 얼마인지 확인하세요.","tool.retirement-calc.desc":"나이, 저축액, 월 납입액을 입력하면 은퇴 시점의 예상 은퇴자금과 4% 룰에 따른 안전한 월 소득, 연도별 성장 스케줄까지 확인할 수 있습니다. 무료, 브라우저에서만 계산.","tool.slope-calc.name":"기울기 계산기","tool.slope-calc.use":"두 점 (x₁, y₁)과 (x₂, y₂)를 입력하면 기울기, 직선의 방정식, 경사각, 퍼센트 경사도, 거리, 중점을 즉시 계산해 드립니다 — 브라우저에서 바로 확인하세요.","tool.slope-calc.desc":"두 점을 입력하면 기울기, 방정식 y=mx+b, 경사각, 퍼센트 경사도, 거리, 중점을 즉시 계산합니다. 무료이며 브라우저에서 처리됩니다.","tool.steps-to-miles-calc.name":"걸음수 마일 변환 계산기","tool.steps-to-miles-calc.use":"실제로 얼마나 걸었을까요? 걸음 수와 키(또는 직접 측정한 보폭)를 입력하면 마일과 킬로미터로 환산한 거리, 걷는 시간, 예상 소모 칼로리를 바로 확인할 수 있습니다.","tool.steps-to-miles-calc.desc":"걸음 수와 키(또는 보폭)를 입력하면 마일과 킬로미터 거리, 걷는 시간, 예상 소모 칼로리를 알 수 있습니다 — 무료, 브라우저에서 전부 계산.","tool.timesheet-calc.name":"타임카드 계산기","tool.timesheet-calc.use":"한 주의 매일 출근·퇴근·무급 휴게 시간을 기록하면 일별·주간 근무시간(소수와 시:분)과 1.5배 초과근무 수당이 자동 반영된 총급여를 브라우저에서 바로 확인할 수 있습니다.","tool.timesheet-calc.desc":"매일 출근·퇴근·휴게 시간을 입력하면 주간 근무시간(소수+시:분)과 주 40시간 초과분 1.5배를 반영한 급여를 계산합니다. 무료, 브라우저에서 바로 계산됩니다.","tool.upside-down-text.name":"거꾸로 텍스트 생성기","tool.upside-down-text.use":"텍스트를 입력하거나 붙여넣으면 즉시 거꾸로 뒤집기·거울 반전·스몰캡스로 변환됩니다 — 무료, 원클릭 복사, 브라우저에서 바로 계산됩니다.","tool.upside-down-text.desc":"유니코드 유사 문자를 이용해 어떤 텍스트든 거꾸로 뒤집거나 거울처럼 반전하거나 스몰캡스로 변환합니다 — 무료, 즉시, 모든 계산이 브라우저에서 이루어집니다。","tool.angle-conv.name":"각도 변환기","tool.angle-conv.use":"각도를 한 번만 입력하면 도, 라디안, 그레이드, 회전으로 즉시 변환됩니다. 자주 쓰는 각도는 정확한 π 분수도 함께 표시됩니다.","tool.angle-conv.desc":"도, 라디안, 그레이드, 회전 사이의 각도를 즉시 변환하며, 자주 쓰는 각도는 정확한 π 분수로, 단위원 표와 도분초(DMS) 모드도 지원합니다.","tool.blood-sugar-conv.name":"혈당 단위 변환기","tool.blood-sugar-conv.use":"어느 칸에든 mg/dL 또는 mmol/L를 입력하면 다른 값과 기준 범위가 즉시 표시됩니다.","tool.blood-sugar-conv.desc":"혈당을 mg/dL와 mmol/L 사이에서 양방향으로 즉시 변환하고 공복·식후 기준 범위까지 확인하세요 — 모든 계산은 브라우저에서 처리됩니다.","tool.chmod-calc.name":"Chmod 계산기","tool.chmod-calc.use":"소유자·그룹·기타 사용자의 읽기·쓰기·실행을 켜고 끄면 8진수 코드, 심볼릭 표기, chmod 명령어가 즉시 업데이트됩니다.","tool.chmod-calc.desc":"체크박스, 8진수(755), 심볼릭 표기(rwxr-xr-x) 사이에서 파일 권한을 즉시 변환합니다. setuid/setgid/스티키 비트도 지원.","tool.css-minifier.name":"CSS 압축기","tool.css-minifier.use":"CSS를 붙여넣고 압축하세요 — 주석 제거, 공백 압축, hex 색상 축약, 0값 단위를 안전하게 제거합니다. 이미 압축된 CSS를 다시 읽기 좋은 들여쓰기 형태로 정렬할 수도 있습니다. 절감된 용량을 바로 확인하세요.","tool.css-minifier.desc":"주석 제거, 공백 압축, hex 색상 축약, 0값 단위 제거로 CSS를 압축하거나 다시 읽기 좋은 들여쓰기 코드로 정렬합니다. 모든 처리는 브라우저 안에서 이뤄집니다.","tool.energy-conv.name":"에너지 단위 변환기","tool.energy-conv.use":"에너지 값을 한 번만 입력하면 줄, 칼로리, kWh, BTU 등 모든 단위로 즉시 확인 — kJ를 칼로리로 변환하는 기능도 포함.","tool.energy-conv.desc":"줄, kJ, 칼로리, kcal, Wh, kWh, BTU, 풋파운드 사이를 즉시 변환 — kJ를 칼로리로 바꾸는 방법과 식품 칼로리 함정 설명 포함.","tool.find-replace-text.name":"찾아 바꾸기","tool.find-replace-text.use":"텍스트 안의 모든 일치 항목을 한 번에 바꿉니다. 찾을 내용과 바꿀 내용을 입력하고, 하이라이트된 미리보기를 확인한 뒤 적용하세요.","tool.find-replace-text.desc":"대소문자 구분, 단어 단위, 정규식 옵션으로 텍스트를 찾아 바꾸고, 적용 전 실시간 미리보기로 확인하세요.","tool.fuel-economy-conv.name":"연비 변환기","tool.fuel-economy-conv.use":"MPG(US), MPG(UK), L/100km, km/L 중 어느 칸에 연비 값을 입력해도 나머지 칸이 즉시 업데이트됩니다. 참고: L/100km는 반대 방향으로, 여기서는 낮은 값이 더 좋습니다.","tool.fuel-economy-conv.desc":"MPG(US), MPG(UK), L/100km, km/L 사이의 연비를 즉시 상호 변환하세요 — 어느 칸에 입력해도 나머지가 자동으로 업데이트됩니다. 흔한 수치 비교표 포함, 모든 계산은 브라우저에서 실행됩니다.","tool.gcf-lcm-calc.name":"최대공약수·최소공배수 계산기","tool.gcf-lcm-calc.use":"2~10개의 정수를 입력하면 최대공약수와 최소공배수를 바로 확인할 수 있습니다 — 계산할 때마다 소인수분해와 유클리드 호제법 풀이 과정도 함께 보여줍니다.","tool.gcf-lcm-calc.desc":"2~6개 정수의 최대공약수(GCF/GCD)와 최소공배수(LCM)를 소인수분해와 유클리드 호제법 계산 과정과 함께 구해보세요. 무료이며 브라우저에서 바로 계산됩니다.","tool.leap-year-checker.name":"윤년 계산기","tool.leap-year-checker.use":"연도를 입력하면 윤년인지 즉시 확인할 수 있고, 4/100/400으로 나누어떨어지는 규칙도 함께 보여줍니다. 원하는 범위의 윤년 목록과 오늘 기준 다음·이전 윤년도 확인하세요.","tool.leap-year-checker.desc":"어떤 연도든 윤년인지 확인하고, 4/100/400 규칙을 확인하며, 범위 내 윤년 목록과 다음·이전 윤년을 찾을 수 있습니다.","tool.military-time-conv.name":"군대시간 변환기","tool.military-time-conv.use":"0930, 21:45, 9:45 PM처럼 거의 모든 형식으로 시간을 입력하면 군대시간 또는 표준시간을 즉시 변환해 드리고, 소리 내어 읽는 법까지 알려드립니다.","tool.military-time-conv.desc":"군대시간(24시간제)을 표준 12시간제 AM/PM 시간으로, 또는 그 반대로 변환합니다. 유연한 입력 인식과 전체 24시간 참조표를 제공하며, 모든 계산은 브라우저에서 이루어집니다.","tool.power-conv.name":"전력 변환기","tool.power-conv.use":"숫자를 한 번만 입력하면 — 모든 전력 단위로 즉시 확인할 수 있습니다.","tool.power-conv.desc":"와트, 킬로와트, 메가와트, 마력(hp·PS), BTU/h, 피트파운드/초 사이의 전력을 즉시 변환하세요 — 모든 계산은 브라우저에서 처리됩니다.","tool.pressure-conv.name":"압력 변환기","tool.pressure-conv.use":"숫자를 한 번만 입력하면 10가지 압력 단위로 즉시 확인할 수 있습니다.","tool.pressure-conv.desc":"Pa, kPa, MPa, bar, psi, atm, mmHg, inHg 사이의 압력을 즉시 변환합니다 — 입력하는 즉시 8개 단위가 모두 업데이트되며, 모든 계산은 브라우저에서 처리됩니다.","tool.protein-intake-calc.name":"단백질 섭취량 계산기","tool.protein-intake-calc.use":"하루에 단백질을 얼마나 먹어야 할까요? 체중을 입력하고 활동량이나 운동 목표를 선택하면 하루 단백질 섭취 범위(g), 끼니별 배분, 그리고 닭가슴살·달걀·두부 같은 간단한 식품 환산량을 바로 확인할 수 있습니다.","tool.protein-intake-calc.desc":"체중과 활동량 또는 목표를 입력하면 하루 단백질 섭취 범위(g), 끼니별 배분, 식품 환산량을 알 수 있습니다. 무료·광고 없음·브라우저에서 계산.","tool.quadratic-solver.name":"이차방정식 계산기","tool.quadratic-solver.use":"계수 a, b, c를 입력해 ax² + bx + c = 0을 풀어보세요 — 근, 판별식, 대입 과정, 꼭짓점을 즉시 확인할 수 있습니다.","tool.quadratic-solver.desc":"a, b, c를 입력하면 어떤 이차방정식이든 즉시 풀립니다. 실근·중근·허근(복소수근), 판별식, 대입 과정, 꼭짓점까지 한 번에 확인하세요. 무료이며 모든 계산은 브라우저에서 이루어집니다.","tool.random-team-gen.name":"랜덤 팀 생성기","tool.random-team-gen.use":"명단을 붙여넣고 팀 수(또는 팀당 인원수)를 정하면 한 번의 클릭으로 공정하고 진짜 무작위인 분배 결과를 받을 수 있습니다.","tool.random-team-gen.desc":"이름을 붙여넣고 팀 수나 인원수 기준으로 공정하게 무작위 분배하세요. 암호학적 난수 셔플을 사용하며 남는 인원은 고르게 나뉩니다. 언제든 다시 섞기 가능 — 무료이며 브라우저에서 실행됩니다.","tool.random-word-gen.name":"랜덤 단어 생성기","tool.random-word-gen.use":"랜덤 단어가 필요하신가요? 명사·동사·형용사 중 카테고리를 고르고 선택적 필터를 추가하면 픽셔너리, 글쓰기 소재, 각종 단어 게임용 목록을 즉시 만들어 드립니다.","tool.random-word-gen.desc":"명사·동사·형용사로 필터링한 랜덤 영어 단어를 시작 글자와 길이까지 지정해 생성하세요. 픽셔너리, 브레인스토밍, 단어 게임에 유용 — 무료, 브라우저에서 계산.","tool.subnet-calc.name":"IP 서브넷 계산기","tool.subnet-calc.use":"내 서브넷은 무엇일까? IPv4 주소와 CIDR 프리픽스(또는 서브넷마스크)를 입력하면 네트워크·브로드캐스트·사용 가능한 호스트 범위를 즉시 확인할 수 있습니다.","tool.subnet-calc.desc":"IPv4 주소와 CIDR 프리픽스 또는 서브넷마스크를 입력하면 네트워크 주소, 브로드캐스트 주소, 사용 가능한 호스트 범위, 2진수 분석까지 즉시 확인할 수 있습니다. 모든 계산은 브라우저에서 처리됩니다.","tool.week-number-check.name":"오늘의 주차","tool.week-number-check.use":"지금은 몇 주차일까요? 페이지를 열자마자 이번 주 ISO 8601 주차를 바로 확인하고, 원하는 날짜의 주차를 조회하거나, 월요일~일요일 기준 1년치 주간 날짜 범위를 살펴보세요.","tool.week-number-check.desc":"오늘의 ISO 8601 주차를 즉시 확인하고, 원하는 날짜의 주차를 조회하며, 1년치 주간 날짜 범위를 살펴보세요 — 모든 계산은 브라우저에서 처리됩니다.","tool.whitespace-remover.name":"여백 제거 도구","tool.whitespace-remover.use":"텍스트를 붙여넣으면 연속된 공백을 즉시 하나로 합치고, 각 줄 앞뒤 공백을 정리하고, 탭을 제거하고, 빈 줄을 삭제하거나 모든 종류의 공백 문자를 없앨 수 있습니다 — 눈에 보이지 않는 줄바꿈 방지 공백과 제로폭 문자까지 포함해서요.","tool.whitespace-remover.desc":"텍스트를 붙여넣어 연속 공백을 합치고, 줄 앞뒤 공백을 정리하고, 탭을 제거하고, 빈 줄을 삭제하거나 모든 공백을 제거하세요 — 눈에 보이지 않는 줄바꿈 방지 공백과 제로폭 문자까지 포함해 전부 브라우저에서 처리됩니다.","tool.xml-formatter.name":"XML 포맷터","tool.xml-formatter.use":"XML을 붙여넣으면 즉시 정렬·검증·압축할 수 있습니다 — CDATA, 주석, XML 선언이 그대로 보존되며 오류가 발생한 정확한 줄을 보여줍니다. 아무것도 브라우저 밖으로 나가지 않습니다.","tool.xml-formatter.desc":"XML을 붙여넣어 스페이스 2/4칸 또는 탭 들여쓰기로 정렬하거나, 한 줄로 압축하거나, 검증해서 오류의 정확한 줄을 확인하세요 — 모두 브라우저에서, CDATA와 주석을 보존한 채로.","tool.alarm-clock.name":"온라인 알람 시계","tool.alarm-clock.use":"하나 이상의 알람을 설정하세요 — +5분 같은 빠른 프리셋이나 정확한 기상 시간을 선택하면, 이 무료 온라인 알람 시계가 소리와 선택적 알림으로 울립니다. 설치도 계정도 필요 없이 이 브라우저 탭 안에서 전부 동작합니다.","tool.alarm-clock.desc":"정확한 알람 시간이나 빠른 +5/+10/+30분 프리셋을 설정하고 실시간 시계를 확인하며, 울릴 때 소리와 알림을 받으세요. 최대 5개의 알람을 저장 — 모두 브라우저에서, 설치 불필요.","tool.cat-age-calc.name":"고양이 나이 계산기","tool.cat-age-calc.use":"우리 냥이는 사람 나이로 몇 살일까요? 고양이 나이를 입력하면(또는 사람 나이에서 역산하면) 수의학 공식으로 즉시 환산하고, 새끼묘부터 노령묘까지 생애주기도 함께 보여드립니다.","tool.cat-age-calc.desc":"수의학 단계별 공식으로 고양이 나이를 사람 나이로 환산하고 생애주기를 확인하세요. 역변환 모드도 지원. 무료, 브라우저에서만 계산.","tool.date-add-calc.name":"날짜 계산기","tool.date-add-calc.use":"기준 날짜를 고르고 일·주·월·년을 더하거나 빼면, 결과 날짜와 요일이 즉시 표시됩니다.","tool.date-add-calc.desc":"원하는 날짜에 일·주·월·년을 더하거나 빼서 요일과 함께 결과를 확인하세요. 선택적 영업일 모드는 주말을 제외합니다.","tool.hourly-to-salary-calc.name":"시급 연봉 환산기","tool.hourly-to-salary-calc.use":"위에 시급 또는 연봉을 입력하면 주급·월급·연봉이 즉시 표시됩니다. 방향은 언제든 바꿀 수 있어요.","tool.hourly-to-salary-calc.desc":"시급을 주급·월급·연봉으로 환산하거나 그 반대로 계산합니다 — 브라우저에서 즉시.","tool.html-entity-conv.name":"HTML 엔티티 인코더/디코더","tool.html-entity-conv.use":"특수문자를 HTML 엔티티로 바꾸거나, 뒤섞인 엔티티를 다시 일반 텍스트로 되돌리세요. 예약 문자는 항상 안전하게 이스케이프되고, 이름이 있는 엔티티는 이름형으로 표시되며, 모든 처리가 브라우저 안에서 즉시 이뤄집니다.","tool.html-entity-conv.desc":"텍스트를 HTML 엔티티로 변환하거나(이름이 있으면 이름형, 없으면 숫자형) 뒤섞인 엔티티를 다시 텍스트로 디코딩하세요. 모든 처리가 브라우저 안에서 이뤄집니다.","tool.moon-phase-calc.name":"달의 위상 계산기","tool.moon-phase-calc.use":"오늘 달의 위상, 조도, 월령을 한눈에 확인하거나 과거·미래의 원하는 날짜를 조회하세요 — 다음 보름달과 삭 날짜까지 함께 보여줍니다.","tool.moon-phase-calc.desc":"오늘 달의 위상과 조도를 바로 확인하거나 원하는 날짜를 조회하세요. 월령과 다음 보름달·삭 날짜를 보여주는 근사 계산 도구로, 오차는 약 ±1일입니다.","tool.name-picker.name":"랜덤 이름 뽑기","tool.name-picker.use":"명단을 붙여넣고 필요한 당첨자 수를 정하면, 내장된 무작위 추첨 기능이 공정하게 뽑아드립니다 — 결과 공개 전 짧은 서스펜스 애니메이션도 함께요.","tool.name-picker.desc":"이름을 붙여넣고 한 번에 뽑을 당첨자 수를 정하면 애니메이션과 함께 공정한 결과를 확인할 수 있어요. 당첨자 제거나 회차별 중복 방지도 가능 — 무료, 개인정보 보호.","tool.remove-duplicate-lines.name":"중복 줄 제거","tool.remove-duplicate-lines.use":"아래에 목록을 붙여넣으세요 — 중복된 줄이 즉시 사라지고, 각 항목은 처음 등장한 줄만 남습니다.","tool.remove-duplicate-lines.desc":"목록을 붙여넣으면 각 항목이 처음 등장한 줄만 남기고 중복 줄을 제거합니다 — 대소문자 무시, 공백 제거, 정렬, 중복만 보기 옵션 제공, 모든 처리는 브라우저에서 이뤄집니다.","tool.ring-size-conv.name":"반지 사이즈 변환기","tool.ring-size-conv.use":"다른 나라 기준으로 내 반지 사이즈는 몇 호일까? US·UK·EU·일본/한국 형식으로, 또는 직접 잰 밀리미터 값을 입력하면 모든 환산값이 즉시 나타납니다.","tool.ring-size-conv.desc":"US/CA, UK/AU 알파벳, EU(둘레 mm), 일본/한국 호수 사이의 반지 사이즈를 전체 조견표와 집에서 측정하는 가이드와 함께 변환합니다.","tool.sql-formatter.name":"SQL 포맷터","tool.sql-formatter.use":"SQL 쿼리를 붙여넣으면 키워드 기준으로 줄바꿈·들여쓰기가 즉시 적용됩니다. 키워드를 대문자, 소문자, 원본 그대로 중에서 선택하거나 압축(Minify) 모드로 전환해 한 줄로 압축할 수도 있습니다. 어떤 데이터도 브라우저 밖으로 나가지 않습니다.","tool.sql-formatter.desc":"SQL 쿼리를 붙여넣으면 키워드 기준 들여쓰기로 정렬하고, 대문자/소문자를 선택하거나 한 줄로 압축할 수 있습니다 — 브라우저에서만 실행됩니다.","tool.binary-text-conv.name":"바이너리 변환기","tool.binary-text-conv.use":"텍스트를 입력하면 즉시 2진수 코드로 바뀌는 것을 확인하세요. 반대로 2진수·16진수·10진수 바이트 값을 붙여넣으면 다시 텍스트로 디코딩됩니다 — 어떤 데이터도 브라우저 밖으로 나가지 않습니다.","tool.binary-text-conv.desc":"텍스트를 2진수·16진수·10진수 바이트 값으로 변환하고 즉시 되돌립니다 — 브라우저에서 바로.","tool.chinese-zodiac-calc.name":"띠 계산기","tool.chinese-zodiac-calc.use":"내 띠는 무엇일까요? 태어난 연도(음력설 전후라면 월/일도)를 입력하면 띠 동물과 오행, 전체 띠 연도표를 바로 확인할 수 있습니다.","tool.chinese-zodiac-calc.desc":"태어난 연도만 입력하면 내 중국식 띠 동물과 오행을 바로 확인할 수 있습니다. 음력설 경계를 정확히 반영하려면 월/일도 추가하세요. 무료, 재미로 즐기는 콘텐츠입니다.","tool.color-contrast-checker.name":"색상 대비 검사기","tool.color-contrast-checker.use":"텍스트 색상과 배경 색상을 고르면 WCAG 명암비와 AA/AAA 통과 배지, 텍스트 미리보기가 즉시 표시됩니다. hex나 RGB 모두 입력 가능하며, 기준 미달 시 통과 가능한 색조를 제안합니다.","tool.color-contrast-checker.desc":"텍스트 색상과 배경 색상을 입력하면 WCAG 명암비, AA/AAA 통과 배지, 실시간 미리보기, 접근성 색상 제안까지 바로 확인할 수 있습니다. 무료, 브라우저에서 계산.","tool.cron-parser.name":"크론 표현식 파서","tool.cron-parser.use":"*/15 9-17 * * 1-5 같은 크론 표현식을 입력하면 무슨 뜻인지 쉬운 문장으로 알려주고, 다음 5번의 실행 시각도 보여줍니다.","tool.cron-parser.desc":"5필드 크론 표현식을 입력하면 이해하기 쉬운 일정 설명, 다음 5회 실행 시각, 필드별 분석 결과를 브라우저에서 바로 확인할 수 있습니다.","tool.csv-to-json.name":"CSV to JSON 변환기","tool.csv-to-json.use":"CSV를 붙여넣거나 파일을 드롭하세요 — 따옴표 필드, 구분자, 숫자 타입까지 알아서 처리된 깔끔한 JSON 객체 배열을 바로 얻을 수 있습니다.","tool.csv-to-json.desc":"CSV 파일을 붙여넣거나 드롭하면 깔끔한 JSON 객체 배열을 얻을 수 있습니다 — 따옴표 필드, 구분자 감지, 숫자/불리언 타입 변환까지 모두 브라우저에서 자동 처리됩니다.","tool.gradient-generator.name":"CSS 그라디언트 생성기","tool.gradient-generator.use":"그라디언트 유형을 고르고 컬러 스톱을 드래그한 뒤 완성된 CSS를 복사하세요 — 디자인하는 즉시 미리보기가 갱신됩니다.","tool.gradient-generator.desc":"비주얼 컬러 스톱 편집기로 선형·방사형·원뿔형 CSS 그라디언트를 디자인하고 완성된 CSS를 즉시 복사하세요.","tool.gst-calc.name":"GST 계산기","tool.gst-calc.use":"순액에 GST를 추가하거나 합계에서 GST를 빼보세요 — 인도 세율 구간(5/12/18/28%)이나 호주·뉴질랜드·싱가포르 세율을 선택하거나 직접 입력할 수 있습니다. 순액, GST, 합계를 즉시 확인하고, 인도의 경우 CGST + SGST 분할도 함께 보여줍니다.","tool.gst-calc.desc":"어떤 세율에서도 GST를 추가하거나 제거하세요: 인도 세율 구간(5/12/18/28%), 호주(10%), 뉴질랜드(15%), 싱가포르(9%)에 CGST/SGST 분할까지. 무료, 모든 계산은 브라우저에서 처리됩니다.","tool.inflation-calc.name":"인플레이션 계산기","tool.inflation-calc.use":"그때의 1달러가 지금 얼마인지, 그리고 물가가 그중 얼마를 가져갔는지.","tool.inflation-calc.desc":"금액, 평균 연간 인플레이션율, 연수를 입력하면 미래 구매력을 알 수 있습니다. 방향을 바꾸면 과거 금액이 오늘날 얼마인지도 확인할 수 있습니다. 무료, 브라우저에서 완전히 실행됩니다.","tool.json-to-csv.name":"JSON to CSV 변환기","tool.json-to-csv.use":"객체로 이루어진 JSON 배열을 붙여넣으면 즉시 깔끔하고 올바르게 따옴표 처리된 CSV를 얻을 수 있습니다 — 중첩된 객체는 점 표기 열로 평탄화되고, 헤더는 모든 객체를 아울러 병합되며, 결과를 복사하거나 다운로드할 수 있습니다. 모든 처리는 브라우저 안에서 이루어집니다.","tool.json-to-csv.desc":"객체로 이루어진 JSON 배열을 붙여넣으면 즉시 깔끔한 CSV를 얻을 수 있습니다 — 중첩된 객체는 점 표기 열로 평탄화되고, RFC 4180 규격의 올바른 따옴표 처리, 쉼표/세미콜론/탭 구분자 선택이 가능하며, 모든 처리는 브라우저 안에서 이루어집니다.","tool.markdown-preview.name":"마크다운 미리보기","tool.markdown-preview.use":"왼쪽에 마크다운을 입력하거나 붙여넣으면 오른쪽에서 안전하게 렌더링된 HTML 미리보기가 즉시 업데이트됩니다 — 가입 불필요, 어떤 내용도 브라우저 밖으로 나가지 않습니다.","tool.markdown-preview.desc":"마크다운을 입력하거나 붙여넣으면 제목, 굵게, 링크, 이미지, 표, 코드 블록까지 즉시 안전한 HTML로 렌더링됩니다 — 모든 계산은 브라우저에서 처리됩니다.","tool.oven-temp-conv.name":"오븐 온도 변환기","tool.oven-temp-conv.use":"화씨나 섭씨로 온도를 입력하거나 가스 마크를 선택하면 나머지 두 값이 즉시 업데이트되며, 팬(대류식) 오븐 보정값도 함께 표시됩니다.","tool.oven-temp-conv.desc":"화씨, 섭씨, 가스 마크 사이의 오븐 온도를 즉시 변환하고 팬 오븐 보정값도 확인하세요 — 모든 계산은 브라우저에서 처리됩니다.","tool.remove-line-breaks.name":"줄바꿈 제거기","tool.remove-line-breaks.use":"줄바꿈이 있는 텍스트를 붙여넣으면 즉시 깔끔한 한 덩어리로 합쳐줍니다 — 공백으로 합치기, 공백 없이 합치기, 또는 문단은 유지하면서 PDF 복사 특유의 줄바꿈만 교정하는 스마트 모드 중에서 고르세요.","tool.remove-line-breaks.desc":"텍스트를 붙여넣고 줄바꿈을 제거하세요 — 공백으로 합치기, 공백 없이 합치기, 또는 스마트 모드로 문단을 유지하며 PDF 텍스트를 교정할 수 있습니다. 무료, 브라우저에서 실행됩니다.","tool.reverse-text.name":"텍스트 뒤집기 생성기","tool.reverse-text.use":"아무 텍스트나 입력하거나 붙여넣으면 문자 순서·단어 순서·각 단어 내부 철자, 세 가지로 동시에 뒤집힌 결과를 확인할 수 있습니다. 카드를 클릭하면 복사됩니다.","tool.reverse-text.desc":"문자 순서·단어 순서·각 단어 내부 철자, 세 가지 방식으로 브라우저에서 즉시 텍스트를 뒤집습니다.","tool.shoe-size-conv.name":"신발 사이즈 변환기","tool.shoe-size-conv.use":"US 9는 UK 8이고 EU 42입니다. 차트를 고르고 숫자 하나만 넣으면 나머지가 나옵니다.","tool.shoe-size-conv.desc":"US, UK, EU, cm(일본/아시아) 신발 사이즈를 남성·여성·아동별 전체 사이즈표와 함께 변환합니다.","tool.sort-lines.name":"알파벳 순서 정렬 도구","tool.sort-lines.use":"어떤 목록이든 붙여넣고 A-Z, Z-A, 자연 순서(item2가 item10보다 앞), 길이순, 또는 무작위로 정렬하세요 — 모두 브라우저 안에서 처리됩니다.","tool.sort-lines.desc":"어떤 목록이든 붙여넣고 A-Z, Z-A, 자연 순서, 길이순으로 정렬하거나 무작위로 섞을 수 있습니다 — 대소문자 구분 및 관사 무시 옵션 포함, 모두 브라우저에서 처리됩니다.","tool.square-root-calc.name":"제곱근 계산기","tool.square-root-calc.use":"숫자를 입력하면 제곱근, 세제곱근, n제곱근을 바로 구할 수 있습니다 — 완전제곱수는 정확한 값과 간단한 근호 형태를 함께 보여줍니다.","tool.square-root-calc.desc":"어떤 숫자든 제곱근, 세제곱근, n제곱근을 구합니다. 완전제곱수는 정확한 결과를, 정수는 √72 = 6√2 같은 간단한 근호 형태도 보여줍니다. 무료이며 모든 계산이 브라우저에서 이루어집니다.","tool.standard-deviation-calc.name":"표준편차 계산기","tool.standard-deviation-calc.use":"숫자 목록을 붙여넣으면 표본 및 모집단 표준편차, 분산, 평균, 편차제곱합을 즉시 확인할 수 있습니다. 펼쳐볼 수 있는 단계별 편차 계산 표도 함께 제공됩니다. 모든 계산은 브라우저에서 처리됩니다.","tool.standard-deviation-calc.desc":"숫자 목록을 붙여넣으면 표본 및 모집단 표준편차, 분산, 평균, 편차제곱합을 확인할 수 있으며 단계별 편차 표도 제공됩니다. 무료이며 모든 계산이 브라우저에서 처리됩니다.","tool.text-to-speech.name":"텍스트 음성 변환","tool.text-to-speech.use":"어떤 텍스트든 즉시 음성으로 바꿔보세요. 텍스트를 붙여넣고, 목소리를 고르고, 속도와 음높이를 조절한 뒤 재생 버튼을 누르면 됩니다 — 모든 과정이 브라우저 탭 안에서 끝납니다.","tool.text-to-speech.desc":"텍스트를 붙여넣고 브라우저 내장 음성으로 들어보세요 — 속도와 음높이를 조절한 뒤 재생, 일시정지, 정지할 수 있습니다.","tool.vat-calc.name":"부가가치세 계산기","tool.vat-calc.use":"세전 가격에 VAT를 더하거나 세금 포함 가격에서 VAT를 빼보세요 — 세전 금액, VAT, 세금 포함 금액이 즉시 표시됩니다.","tool.vat-calc.desc":"어떤 세율에서도 세전 가격에 VAT를 더하거나 세금 포함 가격에서 VAT를 빼보세요. 자주 쓰는 세율 바로가기 버튼 제공. 세전 금액, VAT, 세금 포함 금액 내역을 즉시 확인 — 무료, 브라우저에서 바로 실행됩니다.","tool.zodiac-sign-calc.name":"별자리 계산기","tool.zodiac-sign-calc.use":"생년월일을 입력하면 서양(트로피컬) 별자리와 4원소, 3원성, 그리고 가볍게 즐기는 짧은 성격 소개를 확인할 수 있습니다. 12개 별자리 전체의 정확한 날짜 범위도 함께 보여줍니다.","tool.zodiac-sign-calc.desc":"생년월일을 입력해 서양 별자리, 원소, 원성과 함께 재미있는 성격 소개를 확인하세요. 엔터테인먼트 목적입니다.","tool.metronome.name":"온라인 메트로놈","tool.metronome.use":"템포를 설정하거나 탭으로 입력하고, 박자표를 고른 뒤 시작을 누르세요 — 브라우저에서 정확한 박자를 유지하는 군더더기 없는 메트로놈입니다.","tool.metronome.desc":"BPM 슬라이더, 탭 템포, 박자표(2/4, 3/4, 4/4, 6/8)를 갖춘 무료 온라인 메트로놈. 정확한 Web Audio 스케줄링 사용.","tool.ad-copy-limit-check.name":"광고 문구 글자수 검사기","tool.ad-copy-limit-check.use":"제목과 설명을 붙여넣기만 하세요. 모든 셀을 매체의 실제 글자수 제한과 대조해 드립니다.","tool.ad-copy-limit-check.desc":"구글애즈·마이크로소프트 광고·메타·네이버 검색광고용 무료 광고 문구 글자수 counter. 반응형 검색광고 소재 표를 통째로 붙여넣으면 모든 제목과 설명을 실제 글자수 제한과 대조합니다. 한글·일본어·중국어는 구글과 동일하게 1자를 2자로 계산합니다. 모든 처리는 브라우저 안에서 끝납니다.","tool.average-calc.name":"평균 계산기","tool.average-calc.use":"쉼표·공백·줄바꿈으로 구분된 숫자 목록을 붙여넣거나 입력하면, 브라우저 안에서 곧바로 평균·중앙값·최빈값·범위 등을 비공개로 확인할 수 있습니다.","tool.average-calc.desc":"숫자 목록을 붙여넣거나 입력하면 평균, 중앙값, 최빈값, 범위, 최솟값, 최댓값, 합계, 개수, 기하평균을 즉시 계산합니다. 무료·비공개, 모든 계산은 브라우저에서 실행됩니다.","tool.barista-fire-calc.name":"바리스타 파이어 계산기","tool.barista-fire-calc.use":"바리스타 파이어는 파트타임 일이 지출의 일부를 커버해 더 작은 포트폴리오로 반(半)은퇴하는 것을 말합니다. 그래서 투자는 나머지만 감당하면 됩니다. 지출, 예상 파트타임 소득, 목표를 입력해 줄어든 바리스타 파이어 넘버, 완전 FIRE보다 얼마나 적게 필요한지, 그리고 저축이 궤도에 올랐는지 확인하세요. 어떤 통화에서도 작동합니다.","tool.barista-fire-calc.desc":"무료 바리스타 파이어 계산기 — 지출, 예상 파트타임 소득, 인출률을 입력하면 파트타임 일이 지출 일부를 커버할 때 필요한 더 작은 포트폴리오를 보여 줍니다: 당신의 바리스타 파이어 넘버, 완전 FIRE보다 얼마나 적은지, 그리고 지금의 저축으로 거기까지 코스팅할 수 있는지.","tool.cagr-calc.name":"CAGR 계산기","tool.cagr-calc.use":"한 값에 사서 다른 값에 팔았나요? 시작가·종료가와 기간을 입력하면 몇 초 만에 연평균 성장률(CAGR)·총수익률·성장배수가 나옵니다. 연수 또는 날짜로 입력하세요. 어떤 통화에서도 작동합니다.","tool.cagr-calc.desc":"무료 CAGR 계산기: 시작가·종료가·기간을 입력하면 연평균 성장률(CAGR)·총수익률·절대손익·성장배수가 나오고, 연도별 성장 스케줄까지 표시합니다. 로그인·광고 없이 브라우저에서 계산.","tool.calculator.name":"공학용 계산기","tool.calculator.use":"더하기·빼기·곱하기·나누기는 물론, 삼각함수·로그·거듭제곱·괄호·메모리를 쓰는 공학 모드까지 — 어떤 기기에서든 브라우저만으로 작동하는 완전한 계산기입니다.","tool.calculator.desc":"무료 공학용 계산기. 사칙연산, 퍼센트, 괄호, 제곱근, 거듭제곱, 삼각함수(도/라디안), 로그, 메모리, 계산 기록까지 지원하며 모든 계산은 브라우저에서 처리됩니다.","tool.click-speed-test.name":"클릭 속도 테스트 (CPS)","tool.click-speed-test.use":"얼마나 빨리 클릭할 수 있나요? 시간을 선택하고 아래 박스를 클릭하면 실시간 클릭 수가 거북이부터 치타까지의 등급이 매겨진 CPS(초당 클릭 수) 점수로 바뀝니다.","tool.click-speed-test.desc":"1초부터 60초까지 얼마나 빨리 클릭할 수 있는지 테스트하고 거북이부터 치타까지 등급이 매겨진 CPS 점수를 확인하세요. 브라우저에서 완전히 동작합니다.","tool.coast-fire-calc.name":"코스트 파이어 계산기","tool.coast-fire-calc.use":"코스트 파이어는 지금의 투자만으로 저절로 불어나 은퇴 목표 금액에 닿는 지점입니다 — 더 이상의 납입이 필요 없습니다. 나이, 은퇴 나이, 현재 저축, 목표를 입력해 이미 코스팅 중인지, 아니라면 오늘 얼마가 필요한지 확인하세요. 어떤 통화에서도 작동합니다.","tool.coast-fire-calc.desc":"무료 코스트 파이어 계산기 — 나이, 은퇴 나이, 현재 저축, FIRE 목표를 입력하면 추가 납입 없이 오늘의 가치로 목표에 도달하는지 확인합니다.","tool.compound-interest-calc.name":"복리 계산기","tool.compound-interest-calc.use":"내 돈은 얼마나 불어날까요? 원금, 연이율, 기간, 복리 주기를 입력하면 최종 잔액이 즉시 계산됩니다 — 일복리·월복리·분기복리·연복리를 모두 지원하며, 매월 적립액도 선택적으로 추가할 수 있습니다.","tool.compound-interest-calc.desc":"무료 복리 계산기: 원금·연이율·기간·복리 주기(일/월/분기/연)와 선택적인 매월 적립액을 입력하면 최종 잔액·총 적립액·총 이자가 나오고, 연도별 성장 표까지 표시합니다. 로그인·광고 없이 브라우저에서 계산.","tool.final-grade-calc.name":"기말고사 성적 계산기","tool.final-grade-calc.use":"목표 성적을 받으려면 기말고사에서 정확히 몇 점이 필요한지 바로 확인하세요 — A·B·C 등급 빠른 표도 함께.","tool.final-grade-calc.desc":"현재 성적, 목표 성적, 기말고사 반영 비율을 입력하면 기말고사에서 몇 점이 필요한지 바로 알 수 있습니다. A·B·C 등급별 필요 점수표도 함께 제공. 무료, 브라우저에서 계산.","tool.grade-calc.name":"성적 계산기","tool.grade-calc.use":"각 과제의 점수와 반영 비율을 입력하면 현재 가중 평균 성적과 등급이 즉시 업데이트됩니다.","tool.grade-calc.desc":"무료 가중 평균 성적 계산기 — 각 과제의 점수와 반영 비율(%)을 입력하면 현재 과목 평균과 등급을 바로 확인할 수 있으며, 반영 비율 합계가 100%가 아니면 경고를 표시합니다.","tool.height-conv.name":"키 변환기","tool.height-conv.use":"cm, 피트+인치, 미터, 인치 중 어느 칸에 키를 입력해도 나머지 칸이 즉시 업데이트됩니다.","tool.height-conv.desc":"무료 키 변환기 — cm, 피트·인치, 미터, 총 인치 중 어디에 입력해도 즉시 업데이트됩니다. 5'11\" 표기를 인식하고 흔한 키(150–200cm) 빠른 참조표도 제공합니다.","tool.hours-calc.name":"근무시간 계산기","tool.hours-calc.use":"두 시각 사이는 몇 시간일까요? 시작 시각과 종료 시각을 입력하면 시간+분과 소수 시간으로 소요시간을 알려드립니다 — 야간 근무(종료가 익일)는 자동으로 다음 날로 넘어가고, 무급 휴게시간도 자동으로 차감됩니다. 시각에 시간·분을 더하거나 빼고 싶다면 탭을 전환하세요.","tool.hours-calc.desc":"시작 시각과 종료 시각을 입력하면 시:분과 소수 시간으로 소요시간을 계산합니다. 무급 휴게시간을 빼고 야간 근무도 처리하며, 시각에 시간·분을 더하거나 뺄 수도 있습니다.","tool.image-compressor.name":"이미지 압축","tool.image-compressor.use":"사진을 넣고 품질 수준만 고르면 몇 초 만에 더 작은 JPG, PNG, WebP 파일을 얻을 수 있습니다 — 모든 압축은 브라우저 안에서 이루어지며 어디에도 업로드되지 않습니다.","tool.image-compressor.desc":"브라우저에서 바로 JPG, PNG, WebP 사진을 압축하세요. 품질 슬라이더와 선택적 리사이즈로 압축 전후 용량을 확인하고 다운로드 — 무료, 업로드 없음.","tool.image-resizer.name":"이미지 크기 조정","tool.image-resizer.use":"JPG, PNG, WEBP 이미지를 넣으면 정확한 픽셀 크기나 퍼센트로 크기를 조정하고, 포맷과 화질을 선택해 결과를 다운로드할 수 있습니다. 이미지는 브라우저 밖으로 절대 나가지 않습니다.","tool.image-resizer.desc":"JPG, PNG, WEBP 이미지를 정확한 픽셀이나 퍼센트로 크기 조정 — 업로드 없이 브라우저에서 모두 처리됩니다.","tool.lorem-ipsum-gen.name":"로렘 입숨 생성기","tool.lorem-ipsum-gen.use":"디자인 목업에 채움 텍스트가 필요하신가요? 문단, 문장, 단어 중 선택해 클래식 로렘 입숨을 즉시 생성하고, 프로젝트에 바로 복사해 넣으세요 — 일반 텍스트로도, HTML <p> 태그로 감싸서도 가능합니다.","tool.lorem-ipsum-gen.desc":"문단, 문장, 단어 단위로 로렘 입숨(Lorem Ipsum) 채움 텍스트를 생성하세요. 클래식 시작 문구, HTML <p> 감싸기, 실시간 통계를 선택할 수 있습니다. 무료이며 브라우저에서 계산됩니다.","tool.macro-calc.name":"매크로 계산기","tool.macro-calc.use":"하루 섭취 칼로리를 알고 있거나, 신체 정보로 직접 계산하고 싶다면 — 균형식, 저탄수화물, 고단백, 케토, 커스텀 비율 중 하나를 선택해 하루와 매 끼니마다 섭취해야 할 단백질·탄수화물·지방의 정확한 그램 수를 확인할 수 있습니다.","tool.macro-calc.desc":"무료 매크로 계산기 — 하루 섭취 칼로리를 입력하거나 자동으로 계산해서, 원하는 식단 비율에 맞춰 하루 및 한 끼당 단백질·탄수화물·지방을 그램 단위로 확인하세요.","tool.morse-code-translator.name":"모스부호 변환기","tool.morse-code-translator.use":"텍스트를 입력하거나 모스부호를 붙여넣으세요 — 반대쪽 칸이 즉시 업데이트됩니다. 오디오로 재생하거나 결과를 복사할 수 있습니다.","tool.morse-code-translator.desc":"입력하는 즉시 텍스트를 모스부호로, 모스부호를 텍스트로 실시간 변환합니다. 속도를 조절해 모스부호를 오디오로 듣고 전체 알파벳 표도 확인할 수 있습니다. 모든 처리는 브라우저에서 실행됩니다.","tool.mortgage-calc.name":"주택담보대출 계산기","tool.mortgage-calc.use":"대출금 — 또는 주택가격과 계약금 — 그리고 연이율과 대출 기간을 입력하면, 월 상환액, 총이자, 총비용, 연도별 전체 원리금 상환 스케줄을 바로 확인할 수 있습니다.","tool.mortgage-calc.desc":"무료 주택담보대출 계산기: 대출금(또는 주택가격과 계약금), 연이율, 대출 기간을 입력하면 월 상환액·총이자·총상환액·전체 원리금 상환 스케줄을 볼 수 있습니다. 로그인·광고 없이 브라우저에서 계산.","tool.online-notepad.name":"온라인 메모장","tool.online-notepad.use":"입력을 시작하면 자동으로 저장됩니다 — 가입도, 서버도 필요 없고 새로고침해도 내용이 사라지지 않습니다. 단어·글자 수가 실시간으로 갱신되며, 최대 10개의 메모를 각각 따로 보관할 수 있습니다.","tool.online-notepad.desc":"입력하는 즉시 자동 저장되는 무료 온라인 메모장. 실시간 단어·글자 수, .txt 다운로드, 전체 복사, 최대 5개 메모 동시 보관 — 아무것도 업로드되지 않고 브라우저 안에만 남습니다.","tool.pace-calc.name":"러닝 페이스 계산기","tool.pace-calc.use":"거리, 시간, 페이스 중 두 가지를 알고 있나요? 아래에 입력하면 나머지 하나를 바로 계산해 드립니다 — min/km와 min/mi 페이스, km/h와 mph 속도, 선택한 레이스 거리의 전체 구간 기록표까지 함께 확인하세요.","tool.pace-calc.desc":"거리, 시간, 페이스 중 아무 두 값이나 입력하면 나머지 하나를 계산합니다. min/km와 min/mi 페이스, 속도, 전체 구간 기록표까지 확인하세요.","tool.period-calc.name":"생리 계산기","tool.period-calc.use":"생리주기 하나, 숫자 세 개면 충분합니다 — 다음 6번의 생리일과 배란일, 가임기를 확인하세요.","tool.period-calc.desc":"마지막 생리 시작일, 평균 생리주기, 생리 기간을 입력하면 다음 6번의 생리 예정일과 주기별 예상 배란일·가임기를 확인할 수 있습니다. 무료이며 개인정보 없이 브라우저에서 계산됩니다.","tool.pregnancy-due-date-calc.name":"출산예정일 계산기","tool.pregnancy-due-date-calc.use":"마지막 생리 시작일, 수정일, 또는 시험관아기 배아 이식일을 입력하면 출산예정일, 현재 임신 주수, 삼분기별 주요 일정을 바로 볼 수 있습니다.","tool.pregnancy-due-date-calc.desc":"마지막 생리 시작일, 수정일, 또는 시험관아기(IVF) 배아 이식일로 출산예정일을 계산하고, 현재 임신 주수와 삼분기별 주요 일정표까지 확인하세요. 무료, 개인정보 보호, 브라우저에서 계산.","tool.regex-tester.name":"정규식 테스터","tool.regex-tester.use":"패턴과 플래그를 입력하고 테스트 문자열을 붙여넣으면 매치가 실시간으로 하이라이트됩니다 — 캡처 그룹, 매치 개수, 치환 미리보기까지 함께. 모든 처리는 브라우저 안에서 이루어집니다.","tool.regex-tester.desc":"하이라이트된 매치, 캡처 그룹, 치환 미리보기와 함께 JavaScript 정규식을 실시간으로 테스트하세요 — 모든 처리는 브라우저에서 이루어집니다.","tool.tdee-calc.name":"TDEE 계산기","tool.tdee-calc.use":"하루에 얼마나 칼로리를 태울까요? 나이, 성별, 키, 몸무게, 활동 수준을 입력하면 TDEE, 기초대사량, 유지·감량·증량 목표 칼로리를 알려드립니다.","tool.tdee-calc.desc":"나이, 성별, 키, 몸무게, 활동 수준을 입력하면 TDEE, 기초대사량, 감량·증량 목표 칼로리를 알려줍니다.","tool.text-diff.name":"텍스트 비교기","tool.text-diff.use":"아래에 원본 텍스트와 변경된 텍스트를 붙여넣으면 무엇이 추가·삭제·변경되었는지 줄 단위, 단어 단위로 정확히 확인할 수 있습니다.","tool.text-diff.desc":"두 텍스트를 붙여넣으면 추가·삭제·변경된 모든 줄과 단어를 즉시 확인할 수 있습니다. 대소문자와 공백 무시 옵션을 갖춘 무료 도구이며 모든 계산은 브라우저에서 이루어집니다.","tool.typing-test.name":"타자 속도 테스트","tool.typing-test.use":"화면에 나타나는 단어를 입력하며 실시간으로 타자 속도를 확인하세요. 30초·1분·3분 중 선택하면 순 WPM, 정확도, 글자 수를 바로 알 수 있습니다 — 무료, 가입 불필요, 모든 계산이 브라우저에서 이루어집니다.","tool.typing-test.desc":"30초·1분·3분 동안 타자 속도를 테스트하세요. 실제 단어를 입력하면 WPM, 정확도(%), 글자 수를 즉시 확인할 수 있습니다 — 무료, 모든 계산은 브라우저에서 처리됩니다.","guide.heading":"Toolhub 소개","guide.lead":"Toolhub는 일상에서 마주치는 작은 계산과 변환을 위한 무료 웹 도구 모음으로, 계속 늘어나고 있습니다 — 어느 팩이 더 싼지 확인하는 일부터 글의 글자 수를 세는 일까지요. 모든 도구는 열자마자 바로 작동합니다. 설치도, 계정도, 기다림도 없습니다.","guide.useTitle":"필요한 도구 찾기","guide.useBody":"위 목록을 둘러보세요. 금융·쇼핑, 건강·신체, 단위·변환, 날짜·시간, 개발자 도구 같은 카테고리로 정리돼 있습니다. 급하신가요? 검색창에 키워드를 입력하면 — \"단위가격\", \"BMI\", \"타이머\" — 입력하는 대로 목록이 걸러집니다. 아무 도구나 눌러 전용 페이지에서 열 수 있고, 헤더에서 사이트 전체를 14개 언어 중 하나로 바꿀 수 있습니다.","guide.howTitle":"설계부터 프라이버시 중심","guide.howBody":"Toolhub의 모든 도구는 순수 정적 페이지입니다. 입력한 내용은 전부 여러분의 브라우저 안에서만 처리되며 서버로 전송되지 않습니다. 가입도, 넘겨야 할 숫자도 없으니 급여·대출·개인 정산도 안심하고 계산할 수 있습니다. 저장되는 것은 테마와 언어 설정뿐이며, 그마저도 이 브라우저의 로컬 저장소에만 남습니다.","guide.tipTitle":"무료, 그리고 계속 늘어나는 중","guide.tipBody":"모든 도구는 완전 무료이며 구독이나 숨은 비용이 없습니다. 새 도구가 꾸준히 추가되어 출시되는 즉시 이 페이지에 나타나니 즐겨찾기 해두면 좋습니다. 필요한 도구가 없더라도 이미 준비 중일 가능성이 높습니다.","meta.title":"Toolhub — 회원가입 없이 바로 쓰는 무료 웹 도구 모음","meta.description":"가격 비교부터 글자수 세기까지, 생활 속 계산과 변환을 브라우저에서 바로 처리하는 무료 웹 도구 모음. 설치도 회원가입도 필요 없습니다.","nav.theme":"테마 전환","nav.share":"공유하기","nav.language":"언어","hero.lede":"필요한 순간, 설치 없이 바로 쓰는 무료 웹 도구를 모았습니다.","flagship.desc":"크리에이터·인플루언서를 위한 소셜 트렌드 분석 플랫폼. 키워드 분석 · 경쟁사 레이더 · 시그널 아카이브를 한 곳에서.","tools.heading":"도구 모음","tools.viewall":"전체 보기","tools.searchLabel":"도구 검색","tools.searchPlaceholder":"도구 이름으로 검색 (예: 단위가격)","tools.empty":"검색 결과가 없습니다. 다른 검색어로 시도해 보세요.","tool.unit-price.name":"단위가격 계산기","tool.unit-price.use":"가격과 용량만 입력하세요. 어느 쪽이 더 싼지 바로 알려드립니다.","cat.finance":"금융·쇼핑","cat.life":"생활·일상","cat.random":"랜덤·뽑기","cat.dev":"개발자 도구","cat.date":"날짜·시간","cat.health":"건강·신체","cat.units":"단위 변환","cat.text":"텍스트","cat.utility":"유틸리티","tool.unit-price.desc":"대용량 vs 소용량, 어느 쪽이 더 싼지 3초 만에 비교","tool.sleep-cycle-calc.name":"수면 사이클 계산기","tool.sleep-cycle-calc.use":"개운하게 일어나려면 몇 시에 자야 할까요? 90분 수면 주기를 완성하는 취침 시간을 몇 초 만에 알려드립니다.","tool.sleep-cycle-calc.desc":"개운하게 일어나려면 몇 시에 자야 할까요? 90분 수면 주기를 완성하는 취침 시간을 몇 초 만에 알려드립니다.","tool.gpa-calc.name":"GPA 계산기 (학점 계산기)","tool.gpa-calc.use":"과목·학점·성적을 넣으면 어떤 스케일이든 학기 GPA와 누적 GPA가 즉시 나옵니다.","tool.gpa-calc.desc":"과목·학점·성적을 넣으면 어떤 스케일이든 학기 GPA와 누적 GPA가 즉시 나옵니다.","tool.fuel-cost-calc.name":"유류비 계산기","tool.fuel-cost-calc.use":"이번 주행에 기름값 얼마나 들까요? 나라만 고르면 단위와 통화는 맞춰 드려요 — 거리·연비·유가만 입력하세요.","tool.fuel-cost-calc.desc":"이번 주행에 기름값 얼마나 들까요? 거리·연비·유가를 입력하면 바로 알려드립니다.","tool.random-number-gen.name":"랜덤 숫자 생성기","tool.random-number-gen.use":"범위를 정하고 개수를 고르면 편향 없는 무작위 숫자를 바로 얻습니다 — Powerball·Mega Millions·EuroMillions·로또 6/45 자동 번호도 함께.","tool.random-number-gen.desc":"범위를 정하고 개수를 고르면 편향 없는 무작위 숫자를 바로 얻습니다 — Powerball·Mega Millions·EuroMillions·로또 6/45 자동 번호도 함께.","tool.dice-roller.name":"주사위 굴리기","tool.dice-roller.use":"주사위를 골라 굴리거나 2d6+3 같은 주사위 표기를 입력하세요. 공정한 결과를 브라우저 안에서.","tool.dice-roller.desc":"주사위를 골라 굴리거나 2d6+3 같은 주사위 표기를 입력하세요. 공정한 결과를 브라우저 안에서.","tool.coin-flipper.name":"동전 던지기","tool.coin-flipper.use":"앞면일까 뒷면일까? 동전을 탭하면 검증 가능한 공정한 50/50 결과가 즉시 나옵니다. 한 번에 여러 번 던져 통계를 보거나, 양면에 이름을 붙여 무엇이든 결정하세요.","tool.coin-flipper.desc":"앞면일까 뒷면일까? 동전을 탭하면 검증 가능한 공정한 50/50 결과가 즉시 나옵니다. 한 번에 여러 번 던져 통계를 보거나, 양면에 이름을 붙여 무엇이든 결정하세요.","tool.url-encoder.name":"URL 인코더 / 디코더","tool.url-encoder.use":"URL을 즉시 퍼센트 인코딩·디코딩하세요. Component 또는 Full-URL 모드를 고르고 form(+) 인코딩을 켜면, 한글·이모지·CJK 등 모든 문자가 그대로 보존됩니다. 데이터는 브라우저를 벗어나지 않습니다.","tool.url-encoder.desc":"URL을 즉시 퍼센트 인코딩·디코딩하세요. Component 또는 Full-URL 모드를 고르고 form(+) 인코딩을 켜면, 한글·이모지·CJK 등 모든 문자가 그대로 보존됩니다. 데이터는 브라우저를 벗어나지 않습니다.","tool.hash-gen.name":"해시 생성기","tool.hash-gen.use":"텍스트를 붙여넣거나 파일을 끌어다 놓으면 그 MD5, SHA-1, SHA-256, SHA-384, SHA-512 해시를 즉시 얻습니다. 예상 값을 붙여넣어 체크섬을 검증하세요. 모두 브라우저 안에서 처리됩니다.","tool.hash-gen.desc":"텍스트를 붙여넣거나 파일을 끌어다 놓으면 그 MD5, SHA-1, SHA-256, SHA-384, SHA-512 해시를 즉시 얻습니다. 예상 값을 붙여넣어 체크섬을 검증하세요. 모두 브라우저 안에서 처리됩니다.","tool.color-picker.name":"컬러 피커 & 변환기","tool.color-picker.use":"색을 고르거나 아무 코드나 붙여 넣으면 HEX·RGB·HSL·HSV·CMYK를 즉시 얻고 한 번의 클릭으로 복사합니다. 모든 것은 브라우저 안에 남습니다.","tool.unix-timestamp-conv.name":"유닉스 타임스탬프 변환기","tool.unix-timestamp-conv.use":"로그에서 복사한 숫자를 붙여넣으세요. 단위는 자동으로 알아챕니다.","tool.fraction-calc.name":"분수 계산기","tool.fraction-calc.use":"두 분수를 입력하고 연산을 고르면 기약분수로 약분된 정확한 답을 풀이 과정과 함께 보여줍니다.","tool.prime-checker.name":"소수 판별기","tool.prime-checker.use":"정수를 입력하세요 — 소수인지 즉시 확인하고, 소인수분해까지 볼 수 있습니다.","tool.roman-numeral-conv.name":"로마 숫자 변환기","tool.roman-numeral-conv.use":"숫자나 로마 숫자를 입력하면 반대쪽을 바로, 분해 과정과 함께 보여줍니다.","tool.exchange-rate-conv.name":"환율 계산기","tool.exchange-rate-conv.use":"금액을 입력하고 통화 두 개를 고르면 오늘 환산액이 바로 나옵니다. 기준일은 항상 표시되고, 오프라인에서도 저장된 환율로 계산이 이어집니다.","tool.ovulation-calc.name":"배란일 계산기","tool.ovulation-calc.use":"마지막 생리일 하나로 배란일과 가임기를 달력에서 한눈에 확인하세요.","tool.color-picker.desc":"색을 고르거나 아무 코드나 붙여 넣으면 HEX·RGB·HSL·HSV·CMYK를 즉시 얻고 한 번의 클릭으로 복사합니다. 모든 것은 브라우저 안에 남습니다.","tool.json-formatter.name":"JSON 포매터","tool.json-formatter.use":"JSON을 붙여넣으면 즉시 정렬·검증·압축하고, 오류가 있으면 정확한 줄과 열을 짚어 줍니다. 어떤 것도 브라우저를 벗어나지 않습니다.","tool.json-formatter.desc":"JSON을 붙여넣으면 즉시 정렬·검증·압축하고, 오류가 있으면 정확한 줄과 열을 짚어 줍니다. 어떤 것도 브라우저를 벗어나지 않습니다.","tool.base64-conv.name":"Base64 인코더 / 디코더","tool.base64-conv.use":"텍스트든 이미지든 Base64를 즉시 인코딩·디코딩하세요. 완전한 UTF-8 지원(한글·이모지·CJK), URL-safe 옵션, 그리고 모든 처리가 브라우저 안에 머뭅니다.","tool.base64-conv.desc":"텍스트든 이미지든 Base64를 즉시 인코딩·디코딩하세요. 완전한 UTF-8 지원(한글·이모지·CJK), URL-safe 옵션, 그리고 모든 처리가 브라우저 안에 머뭅니다.","tool.uuid-gen.name":"UUID 생성기","tool.uuid-gen.use":"생성을 누르면 새 RFC 4122 UUID가 나옵니다. 한 번에 최대 500개까지 만들어 모두 복사하세요.","tool.uuid-gen.desc":"생성을 누르면 새 RFC 4122 UUID가 나옵니다. 한 번에 최대 500개까지 만들어 모두 복사하세요.","tool.child-height-predictor.name":"아이 키 예측 계산기","tool.child-height-predictor.use":"우리 아이는 얼마나 클까요? 엄마·아빠 키로 성인 키를 몇 초 만에 추정하세요.","tool.child-height-predictor.desc":"우리 아이는 얼마나 클까요? 엄마·아빠 키로 성인 키를 몇 초 만에 추정하세요.","tool.speed-conv.name":"속도 단위 변환기","tool.speed-conv.use":"숫자를 한 번만 입력하세요 — 모든 속도 단위로 즉시 보여줍니다.","tool.speed-conv.desc":"숫자를 한 번만 입력하세요 — 모든 속도 단위로 즉시 보여줍니다.","tool.case-converter.name":"대소문자 변환기","tool.case-converter.use":"텍스트를 붙여넣으면 모든 케이스를 한 번에 — UPPERCASE·소문자·Title·camelCase·snake_case 등. 카드를 클릭해 복사하세요.","tool.case-converter.desc":"텍스트를 붙여넣으면 모든 케이스를 한 번에 — UPPERCASE·소문자·Title·camelCase·snake_case 등. 카드를 클릭해 복사하세요.","tool.blood-alcohol-calc.name":"혈중 알코올농도 계산기 (BAC)","tool.blood-alcohol-calc.use":"마신 술을 입력하고 추정 혈중 알코올농도를 확인하세요 — 교육용 안내일 뿐, 운전해도 된다는 신호가 아닙니다.","tool.blood-alcohol-calc.desc":"마신 술을 입력하고 추정 혈중 알코올농도를 확인하세요 — 교육용 안내일 뿐, 운전해도 된다는 신호가 아닙니다.","tool.data-size-conv.name":"데이터 용량 변환기","tool.data-size-conv.use":"숫자를 한 번만 입력하면 모든 데이터 단위로 즉시 보여줍니다. 십진과 이진을 나란히 확인하세요.","tool.data-size-conv.desc":"숫자를 한 번만 입력하면 모든 데이터 단위로 즉시 보여줍니다. 십진과 이진을 나란히 확인하세요.","tool.ideal-weight-calc.name":"적정 체중 계산기","tool.ideal-weight-calc.use":"적정 체중은 하나의 숫자가 아닙니다 — 신뢰할 수 있는 4가지 공식과 건강한 BMI 범위를 한눈에 비교하세요.","tool.ideal-weight-calc.desc":"적정 체중은 하나의 숫자가 아닙니다 — 신뢰할 수 있는 4가지 공식과 건강한 BMI 범위를 한눈에 비교하세요.","tool.water-intake-calc.name":"물 섭취량 계산기","tool.water-intake-calc.use":"숫자 하나면 충분합니다. 오늘 마실 물의 양을 컵과 생수병으로 확인하세요.","tool.water-intake-calc.desc":"숫자 하나면 충분합니다. 오늘 마실 물의 양을 컵과 생수병으로 확인하세요.","tool.workday-calc.name":"근무일 계산기","tool.workday-calc.use":"두 날짜만 고르세요. 주말과 공휴일은 자동으로 빼드립니다.","tool.workday-calc.desc":"두 날짜만 고르세요. 주말과 공휴일은 자동으로 빼드립니다.","tool.time-zone-conv.name":"시간대 변환기","tool.time-zone-conv.use":"시각과 도시 몇 곳만 고르세요. 시차와 서머타임은 저희가 계산해 드려요.","tool.time-zone-conv.desc":"시각과 도시 몇 곳만 고르세요. 시차와 서머타임은 저희가 계산해 드려요.","tool.area-conv.name":"넓이 단위 변환기","tool.area-conv.use":"숫자를 한 번만 입력하면 모든 넓이 단위로 즉시 보여줍니다.","tool.area-conv.desc":"숫자를 한 번만 입력하면 모든 넓이 단위로 즉시 보여줍니다.","tool.volume-conv.name":"부피 단위 변환기","tool.volume-conv.use":"숫자를 한 번만 입력하면 모든 부피 단위로 즉시 보여줍니다.","tool.volume-conv.desc":"숫자를 한 번만 입력하면 모든 부피 단위로 즉시 보여줍니다.","tool.tip-calc.name":"팁 계산기","tool.tip-calc.use":"팁은 얼마가 적당할까요? 청구 금액만 입력하면 팁과 1인당 금액이 바로 나옵니다.","tool.tip-calc.desc":"팁은 얼마가 적당할까요? 청구 금액만 입력하면 팁과 1인당 금액이 바로 나옵니다.","tool.split-bill-calc.name":"더치페이 계산기","tool.split-bill-calc.use":"총액 ÷ 인원 — 팁과 올림까지 자동. 1인당 금액을 단톡방에 복사하세요.","tool.split-bill-calc.desc":"총액 ÷ 인원 — 팁과 올림까지 자동. 1인당 금액을 단톡방에 복사하세요.","tool.calorie-calc.name":"칼로리 소모 계산기","tool.calorie-calc.use":"방금 그 운동, 몇 kcal 태웠을까요? 입력 3개, 답은 3초.","tool.calorie-calc.desc":"방금 그 운동, 몇 kcal 태웠을까요? 입력 3개, 답은 3초.","tool.word-counter.name":"단어수 세기","tool.word-counter.use":"텍스트를 붙여넣으면 즉시 계산됩니다 — 단어·글자·문장·문단, 그리고 읽기·말하기 시간까지.","tool.word-counter.desc":"텍스트를 붙여넣으면 즉시 계산됩니다 — 단어·글자·문장·문단, 그리고 읽기·말하기 시간까지.","tool.weight-conv.name":"무게 단위 변환기","tool.weight-conv.use":"숫자를 한 번만 입력하면 9개 질량 단위로 즉시 보여줍니다.","tool.weight-conv.desc":"숫자를 한 번만 입력하면 9개 질량 단위로 즉시 보여줍니다.","tool.stopwatch.name":"온라인 스톱워치","tool.stopwatch.use":"스페이스로 시작·일시정지, L로 랩. 백그라운드 탭에서도 정확합니다.","tool.stopwatch.desc":"스페이스로 시작·일시정지, L로 랩. 백그라운드 탭에서도 정확합니다.","tool.temp-conv.name":"온도 변환기","tool.temp-conv.use":"아무 칸에나 입력하세요 — 나머지 두 칸이 즉시 바뀝니다.","tool.temp-conv.desc":"아무 칸에나 입력하세요 — 나머지 두 칸이 즉시 바뀝니다.","tool.length-conv.name":"길이 단위 변환기","tool.length-conv.use":"숫자를 한 번만 입력하면 8개 길이 단위로 즉시 보여줍니다.","tool.length-conv.desc":"숫자를 한 번만 입력하면 8개 길이 단위로 즉시 보여줍니다.","tool.loan-calc.name":"대출 계산기","tool.loan-calc.use":"대출 금액·금리·기간을 입력하면 월 상환액·총이자·전체 상환 스케줄이 즉시 표시되고, 세 가지 상환방식을 한 화면에서 비교합니다.","tool.loan-calc.desc":"대출 금액·금리·기간을 입력하면 월 상환액·총이자·전체 상환 스케줄이 즉시 표시되고, 세 가지 상환방식을 한 화면에서 비교합니다.","tool.savings-calc.name":"적금 계산기","tool.savings-calc.use":"매달 저축하면 만기에 얼마가 될까요? 몇 초 만에 만기 수령액을 확인하세요 — 세전 이자, 떼는 세금, 손에 쥐는 실수령액까지. 통화 상관없이 씁니다.","tool.savings-calc.desc":"매달 저축하면 만기에 얼마가 될까요? 몇 초 만에 만기 수령액을 확인하세요 — 세전 이자, 떼는 세금, 손에 쥐는 실수령액까지. 통화 상관없이 씁니다.","tool.body-fat-calc.name":"체지방률 계산기","tool.body-fat-calc.use":"인바디 없이 — 줄자 하나로 내 체지방률을 추정하세요.","tool.body-fat-calc.desc":"인바디 없이 — 줄자 하나로 내 체지방률을 추정하세요.","tool.world-clock.name":"세계 시계","tool.world-clock.use":"도시를 추가하면 시계가 돌기 시작합니다. 시차는 저희가 계산해 드려요.","tool.world-clock.desc":"도시를 추가하면 시계가 돌기 시작합니다. 시차는 저희가 계산해 드려요.","tool.bmr-calc.name":"기초대사량 계산기","tool.bmr-calc.use":"숨만 쉬어도 쓰는 칼로리, 두 가지 공식으로 정확하게 확인하세요.","tool.bmr-calc.desc":"숨만 쉬어도 쓰는 칼로리, 두 가지 공식으로 정확하게 확인하세요.","tool.countdown-timer.name":"카운트다운 타이머","tool.countdown-timer.use":"시간을 정하고 시작을 누르세요. 백그라운드 탭에서도 끝나는 순간 울립니다.","tool.countdown-timer.desc":"시간을 정하고 시작을 누르세요. 백그라운드 탭에서도 끝나는 순간 울립니다.","tool.qr-gen.name":"QR 코드 생성기","tool.qr-gen.use":"입력하는 순간 QR 코드가 만들어집니다. 가입도, 만료도, 서버 전송도 없습니다.","tool.qr-gen.desc":"입력하는 순간 QR 코드가 만들어집니다. 가입도, 만료도, 서버 전송도 없습니다.","tool.date-diff-calc.name":"날짜 차이 계산기","tool.date-diff-calc.use":"두 날짜만 고르세요. 며칠 지났는지, 몇 년 몇 개월인지 바로 나옵니다.","tool.date-diff-calc.desc":"두 날짜만 고르세요. 며칠 지났는지, 몇 년 몇 개월인지 바로 나옵니다.","tool.interest-calc.name":"이자 계산기","tool.interest-calc.use":"목돈을 넣어두면 이자가 얼마 붙을까? 단리·복리, 세금 떼고 실제 받는 금액까지 바로 계산합니다.","tool.interest-calc.desc":"목돈을 넣어두면 이자가 얼마 붙을까? 단리·복리, 세금 떼고 실제 받는 금액까지 바로 계산합니다.","tool.pomodoro-timer.name":"뽀모도로 타이머","tool.pomodoro-timer.use":"25분 집중하고 5분 쉬세요. 사이클은 타이머가 알아서 돌립니다.","tool.pomodoro-timer.desc":"25분 집중하고 5분 쉬세요. 사이클은 타이머가 알아서 돌립니다.","tool.char-count.name":"글자수 세기","tool.char-count.use":"붙여넣기 하면 바로 셉니다. 자소서 500자 제한도, 리포트 원고지 매수도.","tool.char-count.desc":"자소서·리포트 글자수, 바이트, 원고지 매수를 붙여넣기 즉시 계산","tool.age-calc.name":"나이 계산기","tool.age-calc.use":"생년월일 하나로 만 나이, 세는나이, 띠까지. 3초면 충분합니다.","tool.age-calc.desc":"만 나이·세는나이·연 나이와 띠를 즉시 확인","tool.bmi-calc.name":"BMI 계산기","tool.bmi-calc.use":"숫자 두 개면 충분합니다. WHO 기준과 아시아 기준을 동시에 확인하세요.","tool.bmi-calc.desc":"키·몸무게 입력으로 체질량지수·비만도 즉시 확인","tool.dday-calc.name":"디데이 계산기","tool.dday-calc.use":"목표일을 선택하면 바로 셉니다. 수능, 기념일, 마감일 — 뭐든.","tool.dday-calc.desc":"수능·기념일·마감일까지 D-day 즉시 계산","tool.discount-calc.name":"할인율 계산기","tool.discount-calc.use":"정가·할인가 입력하면 할인율이 나옵니다. 거꾸로도 됩니다.","tool.discount-calc.desc":"할인율·할인가 즉시 계산, 두 방향 모두","tool.password-gen.name":"비밀번호 생성기","tool.password-gen.use":"광고 없이, 서버 없이 — 암호학적으로 안전한 랜덤 패스워드","tool.password-gen.desc":"서버 없이 — 암호학적으로 안전한 랜덤 패스워드","tool.percent-calc.name":"퍼센트 계산기","tool.percent-calc.use":"공식 외울 필요 없어요. 숫자 넣으면 바로 나옵니다.","tool.percent-calc.desc":"비율·증감률·변화량을 탭 하나로","tool.salary-calc.name":"연봉 실수령액 계산기","tool.salary-calc.use":"연봉을 입력하면 세후 월급이 바로 나옵니다. 2026년 최신 요율 적용.","tool.salary-calc.desc":"연봉 입력 한 번, 세후 월급 즉시 확인","tool.tax-calc.name":"부가세 계산기","tool.tax-calc.use":"금액만 입력하세요. 국가별 부가세율이 자동 적용되어 공급가·부가세·공급대가를 바로 알려드립니다.","tool.tax-calc.desc":"공급가·공급대가 0.3초 즉시 분리","usage.heading":"도구 사용법 & 활용 예시","usage.unit-price.title":"단위가격 계산기 — 이렇게 써보세요","usage.unit-price.body":"마트에서 500g에 4,900원짜리 세제와 1.2kg에 10,900원짜리 세제 중 뭐가 더 싼지 헷갈릴 때, 상품 A·B 칸에 가격과 용량만 넣으면 자동으로 100g당 가격으로 맞춰 비교해 줍니다. 온라인 쇼핑의 \"2+1\" 같은 묶음 상품은 묶음 개수 칸에 낱개 수를 입력하면 총용량 기준으로 정확히 계산됩니다. 회원가입도 설치도 필요 없고, 입력값은 브라우저 밖으로 나가지 않습니다.","usage.char-count.title":"글자수 세기 — 이렇게 써보세요","usage.char-count.body":"자소서 500자 제한을 앞두고 있다면 본문을 그대로 붙여넣기만 하면 공백 포함·제외 글자수와 목표 대비 잔여량이 즉시 표시됩니다. 기업 지원 시스템마다 UTF-8(3byte)과 EUC-KR(2byte) 기준이 달라 혼란스럽다면, 두 기준의 바이트 수를 동시에 보여주므로 어떤 시스템에서도 한 번에 확인할 수 있습니다. 입력한 텍스트는 서버로 전송되지 않고 브라우저 안에서만 계산되므로 민감한 내용도 안심하고 붙여넣을 수 있습니다.","others.heading":"만든 사람의 다른 서비스","others.lede":"Toolhub 를 만든 팀이 운영하는 다른 서비스도 확인해 보세요.","others.sta.desc":"크리에이터·인플루언서 전용 소셜 트렌드 분석 플랫폼","others.isitai.name":"이거 AI야? (isitai.me)","others.isitai.desc":"이미지·영상이 AI로 생성되었는지 무료로 판별","faq.heading":"자주 묻는 질문","faq.q1":"Toolhub는 뭐하는 곳인가?","faq.a1":"Toolhub는 단위가격 계산기처럼 일상에서 바로 쓸 수 있는 무료 웹 도구를 한 곳에 모아둔 온라인 계산기 모음입니다. 회원가입이나 앱 설치 없이 브라우저만 열면 바로 사용할 수 있고, 각 도구는 하나의 문제만 빠르게 해결하도록 만들어졌습니다.","faq.q2":"도구는 전부 무료인가?","faq.a2":"네, Toolhub 에 등재된 모든 웹 유틸리티 모음은 완전 무료입니다. 결제나 구독 없이 설치 없는 계산기를 그대로 사용하시면 됩니다. 별도 유료 기능이 생기면 도구 페이지에 명시적으로 안내합니다.","faq.q3":"데이터가 서버로 전송되나?","faq.a3":"아니오. Toolhub 에 등재된 도구들은 pure-static 방식으로 만들어져 입력값을 서버로 전송하지 않고 브라우저 안에서만 계산합니다. 테마·언어 등 설정값은 이 브라우저의 localStorage 에만 남고, 외부로 전송되지 않습니다.","faq.q4":"새 도구는 얼마나 자주 나오나?","faq.a4":"새 도구와 개선 사항은 준비가 끝나면 공개합니다. 이 목록에서 현재 이용 가능한 도구를 확인할 수 있으며, 고정된 주간 출시 일정은 없습니다.","footer.privacy":"개인정보처리방침","footer.more":"다른 도구 보기","footer.credit":"만든 사람: rayv","footer.coffee":"☕ 커피 한 잔 사주기","why.heading":"Toolhub를 쓰는 이유","why.free.title":"가입 없이, 언제나 무료","why.free.body":"모든 도구가 완전 무료이며 계정 없이 작동합니다. 열어서 바로 시작하세요 — 설치도, 구독도, 숨은 비용도 없습니다.","why.private.title":"브라우저에서 실행","why.private.body":"모든 처리가 내 기기에서 이루어집니다. 입력한 내용은 브라우저 안에서만 처리되고 밖으로 나가지 않아 데이터가 안전하게 보호됩니다.","why.maintained.title":"매주 유지보수","why.maintained.body":"모든 도구는 QA 체크리스트를 통과한 뒤에만 공개되며, 계산이 정확하고 링크가 유효하도록 전체 목록을 매주 점검합니다.","footer.about":"소개","footer.contact":"문의","footer.terms":"이용약관","tool.crypto-average-calc.name":"코인 평단가 계산기","tool.crypto-average-calc.use":"한 코인을 여러 번 나눠 샀나요? 매수마다 입력하면 몇 초 만에 가중 평단가·손익분기가·평가손익이 나오고, 물타기 매수까지 계획해 평단을 낮출 수 있습니다. 소수점 코인과 어떤 통화든 지원합니다.","tool.csv-dedupe.name":"CSV 중복 제거","tool.csv-dedupe.use":"중복을 결정할 열을 고르고 목록을 정리하세요 — 업로드 없음, 조용한 삭제 없음.","tool.dca-calc.name":"적립식 투자 계산기","tool.dca-calc.use":"매달 정액을 투자하시나요? 몇 초 만에 미래 포트폴리오를 예측하세요 — 총 투자원금, 시장 수익, 세금, 그리고 물가를 반영한 진짜 가치까지. 통화 상관없이 씁니다.","tool.inventory-turnover.name":"재고회전율","tool.inventory-turnover.use":"SKU별 회전율, 재고일수, 그리고 안 팔리는 재고에 묶인 금액까지 — 모두 브라우저 안에서 계산합니다.","tool.investment-goal-calc.name":"투자 목표 계산기","tool.investment-goal-calc.use":"머릿속에 숫자가 있나요? 목표, 남은 기간, 예상 수익률을 입력하면 그곳에 데려다줄 매달 투자액을 찾아줍니다 — 또는 오늘 한 번에 넣을 수 있는 일시금도. 얼마가 내 돈이고 얼마가 시장 성장인지 확인하세요. 어떤 통화든 작동합니다.","tool.landed-cost-batch.name":"수입원가 일괄 계산기","tool.landed-cost-batch.use":"운임을 전 품목에 안분해 개당 수입원가까지 — 브라우저 안에서, 업로드 없이.","tool.list-compare.name":"두 목록 비교","tool.list-compare.use":"A에만·B에만·양쪽 모두에 있는 항목을 찾으세요 — 브라우저 안에서, 업로드 없이.","tool.manday-estimator.name":"맨먼스 공수 산정 계산기","tool.manday-estimator.use":"WBS를 붙여넣으세요. 인시·인일·인월이 역할별·단계별로 자동 집계되고 인건비까지 나옵니다.","tool.packing-list-cbm.name":"패킹리스트 CBM","tool.packing-list-cbm.use":"수백 줄의 카톤 행을 붙여넣으세요. CBM·청구중량·운임톤·컨테이너 수량을 계정도 업로드도 없이 계산합니다.","tool.paygap-report.name":"성별 임금격차 리포트 빌더","tool.paygap-report.use":"급여 CSV를 올리면 법정 평균/중앙값 시급격차·상여격차·사분위를 뽑아 줍니다 — 전부 브라우저 안에서 계산, 업로드 없음.","tool.perf-rating-calibrator.name":"인사평가 캘리브레이터","tool.perf-rating-calibrator.use":"관대한 평가자와 엄격한 평가자를 같은 잣대로 맞춘 뒤 등급 배분을 적용하세요 — 모두 브라우저 안에서.","tool.pregnancy-week-calc.name":"임신 주수 계산기","tool.pregnancy-week-calc.use":"지금 몇 주인지, 예정일이 언제인지 — 마지막 생리일 하나로 바로 확인하세요.","tool.roi-calc.name":"ROI 계산기","tool.roi-calc.use":"얼마를 투자했고 얼마를 회수했는지 입력하면 몇 초 만에 투자수익률(ROI)·순이익·회수배수가 나옵니다. 보유기간 — 연수 또는 날짜 — 을 더하면 연환산 ROI까지 얻습니다. 어떤 통화에서도 작동합니다.","tool.safety-stock-batch.name":"안전재고","tool.safety-stock-batch.use":"전 SKU를 한 표에. 수요 편차는 이력에서 저희가 계산합니다 — Z값을 찾아볼 필요가 없습니다.","tool.stock-average-calc.name":"주식 평단가 계산기","tool.stock-average-calc.use":"한 종목을 여러 번 나눠 샀나요? 매수마다 입력하면 몇 초 만에 가중 평단가·손익분기가·평가손익이 나오고, 물타기 매수까지 계획할 수 있습니다. 어떤 통화든 지원합니다.","tool.stock-ledger-recon.name":"재고수불부 작성 & 재고실사 대사","tool.stock-ledger-recon.use":"거래 로그로부터 SKU별 기초 → 입고 → 출고 → 기말 잔고를 만들고, 재고실사가 정확히 어디서 안 맞는지 확인하세요 — 전부 브라우저 안에서.","tool.stock-profit-calc.name":"주식 수익 계산기","tool.stock-profit-calc.use":"주식을 팔고 실제로 얼마 남았는지 궁금하신가요? 매수단가·매도단가·수량만 넣으면 몇 초 만에 순손익·수익률·손익분기가 나오고, 매수/매도 수수료·거래세·양도소득세를 더하면 세후 금액까지 나옵니다. 어떤 통화든 지원합니다.","tool.timesheet-batch-agg.name":"근태 일괄 집계","tool.timesheet-batch-agg.use":"타각 원본 CSV를 직원별·주별 근로·연장·야간·휴일 시간으로 변환 — 전부 브라우저에서 계산, 업로드 없음.","tool.aspect-ratio-calc.name":"화면 비율 계산기","tool.aspect-ratio-calc.use":"비율 유지. 새 치수 하나만 넣으면 나머지가 나옵니다.","tool.cooking-conv.name":"컵→그램 변환기","tool.cooking-conv.use":"재료별 부피→무게 변환 — 컵 계량을 정직하게 옮기는 유일한 방법.","tool.dog-age-calc.name":"강아지 나이 계산기","tool.dog-age-calc.use":"7을 곱하는 규칙은 틀렸습니다. 체급과 생애 단계가 전부를 바꿉니다.","tool.one-rep-max-calc.name":"1RM 계산기","tool.one-rep-max-calc.use":"힘든 세트 하나로 1RM 추정 — 그리고 거기서 나오는 실제 훈련 중량까지.","tool.square-footage-calc.name":"면적 계산기","tool.square-footage-calc.use":"치수를 넣으면 면적이, 그리고 실제로 사야 할 자재량이 나옵니다.","tool.number-base-conv.name":"진법 변환기","tool.number-base-conv.use":"아무 진법으로나 입력하면 나머지 진법이 즉시 나옵니다.","tool.color-conv.name":"HEX ↔ RGB 변환기","tool.color-conv.use":"색 하나 넣으면 세 형식 전부 — 디자이너가 놓치는 대비 검사까지.","tool.jwt-decoder.name":"JWT 디코더","tool.jwt-decoder.use":"토큰을 디코드해 클레임과 만료 시각을 확인 — 어디에도 전송하지 않고.","tool.wheel-spinner.name":"랜덤 룰렛","tool.wheel-spinner.use":"한 줄에 하나씩, 한 번 돌려 한 명 — 뺀 뒤 다시 돌릴 수도 있습니다.","tool.sales-tax-calc.name":"미국 판매세 계산기","tool.sales-tax-calc.use":"가격에서 총액으로, 총액에서 가격으로 — 50개 주 기본세율 내장.","tool.overtime-pay-calc.name":"초과근무 수당 계산기","tool.overtime-pay-calc.use":"시간을 넣으면 정규·초과·2배 수당이 분리되어 총액까지 나옵니다.","tool.heart-rate-zone-calc.name":"심박존 계산기","tool.heart-rate-zone-calc.use":"나이와 안정시 심박을 넣으면 5개 존과 각 존이 만드는 적응이 나옵니다.","tool.car-payment-calc.name":"자동차 할부 계산기","tool.car-payment-calc.use":"표시 가격에서 실제 월 납입금까지 — 딜러가 얹는 세금·수수료 포함.","tool.apr-apy-calc.name":"APR APY 계산기","tool.apr-apy-calc.use":"APR과 APY가 달라지는 이유는 단 하나, 복리 주기입니다.","tool.btu-calc.name":"BTU 계산기","tool.btu-calc.use":"면적이 기본값을 정하고 햇빛·천장 높이·사람 수가 이를 움직입니다. 용량이 과하면 방은 춥기만 하고 눅눅해집니다.","tool.concrete-calc.name":"콘크리트 물량 계산기","tool.concrete-calc.use":"슬래브·기초·기둥 치수를 넣으면 야드, 세제곱미터, 포대 수를 로스 포함으로 계산합니다.","tool.csv-diff.name":"Csv Diff","tool.csv-diff.use":"두 CSV 사이에서 무엇이 추가·삭제·변경됐는지 확인하세요 — 브라우저 안에서만 처리하며 업로드하지 않습니다.","tool.dividend-calc.name":"Dividend Calculator","tool.dividend-calc.use":"배당주나 ETF를 보유 중인가요? 주식 수·주가·배당금만 입력하면 몇 초 만에 배당수익률과 연 배당소득이 나옵니다. 재투자를 켜면 세금과 물가상승률까지 반영해 DRIP(배당 재투자)이 여러 해에 걸쳐 자산을 얼마나 불리는지 예측합니다. 어떤 통화든 사용할 수 있습니다.","tool.paint-calc.name":"페인트 계산기","tool.paint-calc.use":"치수만 넣으면 필요한 양이 나옵니다. 문·창문 공제와 2회 도장까지 반영합니다.","tool.rent-affordability-calc.name":"월세 감당액 계산기","tool.rent-affordability-calc.use":"30% 규칙과 연소득 40배 심사선, 그리고 부채가 실제로 남겨주는 여력.","tool.tile-calc.name":"타일 계산기","tool.tile-calc.use":"방 크기, 타일 규격, 로스율 — 결국 이 세 숫자가 구매 수량을 정합니다.","tool.utm-builder.name":"대량 UTM 링크 생성기","tool.utm-builder.use":"값 목록을 한 번만 붙여넣으면 태깅된 캠페인 URL을 전부 만들고 GA4 규칙으로 검증합니다.","tool.vehicle-log-agg.name":"업무용승용차 운행기록부 집계기","tool.vehicle-log-agg.use":"전 차량의 수천 줄짜리 운행기록을 업무사용비율과 손금산입액으로 바꿔 드립니다 — 전부 브라우저 안에서.","tool.wbs-progress-rollup.name":"WBS 가중 진척률","tool.wbs-progress-rollup.use":"WBS를 붙여넣으세요. 가중치가 상위로 집계되고, 지연 작업이 드러나고, 주간보고용 표가 복사됩니다.","tool.workback-schedule.name":"역산 스케줄 빌더","tool.workback-schedule.use":"마감일을 정하고 작업을 붙여넣으세요. 영업일 기준으로 거꾸로 계산해 이미 늦었는지 알려드립니다.","tool.home-affordability-calc.name":"주택 구매력 계산기","tool.home-affordability-calc.use":"대출 기관은 한도를 말합니다. 여기서는 그 한도와 실제로 감당 가능한 가격을 함께 봅니다.","tool.json-diff.name":"JSON Diff","tool.json-diff.use":"JSON 두 개를 붙여넣으면 모든 차이를 전체 경로와 함께 돌려줍니다.","tool.password-strength-checker.name":"비밀번호 강도 검사기","tool.password-strength-checker.use":"내 비밀번호의 실제 엔트로피는 몇 비트이고, 진짜 공격이라면 얼마나 걸릴까요?","tool.paycheck-calc.name":"미국 실수령액 계산기","tool.paycheck-calc.use":"실제로 통장에 들어오는 금액을 봅니다 — 2025년 연방 세율표, FICA, 직접 입력한 주세율 기준.","tool.zakat-calc.name":"자카트 계산기","tool.zakat-calc.use":"가진 것을 더하고 지금 갚아야 할 것을 빼서 니사브와 비교합니다. 2.5%는 그다음입니다.","tool.a1c-calc.name":"당화혈색소 A1C 계산기","tool.a1c-calc.use":"A1C 한 숫자를 혈당계가 쓰는 단위로 바꾸고, ADA 기준 어디에 있는지 확인하세요.","tool.board-foot-calc.name":"보드피트 계산기","tool.board-foot-calc.use":"두께는 쿼터, 너비는 인치, 길이는 피트 — 목재상이 청구하는 그 한 숫자입니다.","tool.bra-size-calc.name":"브라 사이즈 계산기","tool.bra-size-calc.use":"두 번의 측정으로 US·UK·EU 사이즈와, 애매할 때 시도할 시스터 사이즈까지 나옵니다.","tool.car-lease-calc.name":"자동차 리스 계산기","tool.car-lease-calc.use":"리스를 결정하는 건 두 가지입니다. 차가 잃는 값과 돈의 값.","tool.gravel-calc.name":"자갈 계산기","tool.gravel-calc.use":"진입로·마당·배수층에 필요한 자갈을 부피, 무게, 다짐 여유까지 한 번에.","tool.heat-index-calc.name":"열지수 계산기","tool.heat-index-calc.use":"32°C에 습도 70%면 체감 40°C입니다. 위험을 정하는 건 온도계가 아니라 습도입니다.","tool.mpg-calc.name":"연비 계산기","tool.mpg-calc.use":"지난번 주유 영수증의 숫자 두 개면 내 차의 진짜 연비를 알 수 있습니다.","tool.mulch-calc.name":"멀칭 계산기","tool.mulch-calc.use":"화단 크기와 깊이만 넣으면 세제곱야드와 봉지 수가 나옵니다. 자재상에 가기 전에 확인하세요.","tool.number-to-words.name":"숫자 영어 변환기","tool.number-to-words.use":"숫자를 입력하면 영어 단어로 — 은행 수표에 쓰는 정확한 표기까지 함께 나옵니다.","tool.pool-volume-calc.name":"수영장 물량 계산기","tool.pool-volume-calc.use":"가로·세로·수심만 넣으면 염소, 소금, 쇼크 투입량의 기준이 되는 물량이 나옵니다.","tool.readability-checker.name":"가독성 검사기","tool.readability-checker.use":"글을 붙여넣으면 Flesch 점수와 읽기 학년 수준, 그 근거가 된 문장 통계를 함께 보여줍니다.","tool.wind-chill-calc.name":"체감온도 계산기","tool.wind-chill-calc.use":"바람은 피부에 붙어 있던 따뜻한 공기층을 벗겨냅니다. 실제로 얼마나 춥게 느껴지는지 확인하세요.","tool.age-gap-calc.name":"나이 차이 계산기","tool.age-gap-calc.use":"달력 그대로 계산한 두 생일 사이의 연·월·일 — 옛 '나이 절반 더하기 7' 문구까지.","tool.density-calc.name":"밀도 계산기","tool.density-calc.use":"밀도 = 질량 ÷ 부피. 둘만 입력하면 나머지 하나가 모든 단위로 나옵니다.","tool.fence-calc.name":"울타리 계산기","tool.fence-calc.use":"울타리 길이만 재면 기둥·레일·판재·비용까지 자재 목록 전체가 나옵니다.","tool.golf-handicap-calc.name":"골프 핸디캡 계산기","tool.golf-handicap-calc.use":"최근 라운드를 입력하세요. WHS 디퍼렌셜 공식과 저표본 보정을 대신 계산해 드립니다.","tool.half-life-calc.name":"반감기 계산기","tool.half-life-calc.use":"카페인, 탄소-14, 약물 배출까지 공식 하나로 설명됩니다. 아는 값을 넣으면 나머지를 풀어 줍니다.","tool.molar-mass-calc.name":"몰질량 계산기","tool.molar-mass-calc.use":"Ca(OH)2 나 CuSO4.5H2O 같은 화학식을 입력하면 g/mol 과 원소별 질량 비율을 바로 보여줍니다.","tool.ohms-law-calc.name":"옴의 법칙 계산기","tool.ohms-law-calc.use":"두 칸만 채우세요. 나머지 두 값은 대수이고, 도구가 풀이 과정을 보여줍니다.","tool.resistor-color-code.name":"저항 컬러코드 계산기","tool.resistor-color-code.use":"색띠만 고르면 값이 나옵니다. 4밴드·5밴드 저항을 오차 범위까지 해독합니다.","tool.sig-fig-calc.name":"유효숫자 계산기","tool.sig-fig-calc.use":"어떤 자리가 유효한지 눈으로 확인하고, 원하는 유효숫자 자릿수로 반올림하세요.","tool.stair-calc.name":"계단 계산기","tool.stair-calc.use":"바닥에서 바닥까지 높이를 입력하세요. 균등한 챌판 높이와 총 런, 규정을 통과하는 스트링거 길이가 나옵니다.","tool.tank-volume-calc.name":"탱크 용량 계산기","tool.tank-volume-calc.use":"원통형·사각형 탱크의 용량을 갤런으로. 지금 깊이에서 실제로 얼마나 들어 있는지까지.","tool.words-to-pages.name":"단어 수 페이지 변환기","tool.words-to-pages.use":"1,500단어는 몇 페이지일까요? 폰트와 행간이 답을 정합니다 — 둘 다 고르면 실제 분량이 나옵니다.","tool.drywall-calc.name":"석고보드 계산기","tool.drywall-calc.use":"치수를 넣으면 자재 목록이 나옵니다 — 보드·컴파운드·테이프·나사, 손실분까지 포함.","tool.pregnancy-weight-gain-calc.name":"임신 체중 증가 계산기","tool.pregnancy-weight-gain-calc.use":"권장 범위는 임신 전 BMI에서 나옵니다. 모두에게 통하는 하나의 숫자는 없습니다.","tool.roof-pitch-calc.name":"지붕 물매 계산기","tool.roof-pitch-calc.use":"한 번 재면 끝: x/12 물매, 각도, 기울기 %, 서까래 길이까지 함께 나옵니다.","tool.rule-of-72-calc.name":"72 법칙 계산기","tool.rule-of-72-calc.use":"72를 연 수익률로 나누면 두 배 되는 햇수가 바로 나옵니다. 스프레드시트가 필요 없습니다.","tool.sand-calc.name":"모래 계산기","tool.sand-calc.use":"가로·세로·깊이를 넣으면 부피, 무게, 포대 수가 나옵니다.","tool.topsoil-calc.name":"흙(표토) 소요량 계산기","tool.topsoil-calc.use":"물량을 결정하는 건 면적이 아니라 깊이입니다. 10cm만 깔아도 벌크 배송 단위가 됩니다.","tool.wallpaper-calc.name":"벽지 계산기","tool.wallpaper-calc.use":"롤·드롭·패턴 손실을 도배사가 실제로 세는 방식 그대로 계산합니다.","tool.bsa-calc.name":"체표면적 계산기 (BSA)","tool.bsa-calc.use":"공인된 BSA 공식 3종을 한 화면에서, 미터법·야드파운드법 모두 지원하고 평균값까지 보여줍니다.","tool.grass-seed-calc.name":"잔디 씨앗 계산기","tool.grass-seed-calc.use":"적게 뿌리면 잡초가 들어오고, 많이 뿌리면 새싹끼리 서로를 죽입니다.","tool.http-status-lookup.name":"HTTP 상태 코드 조회","tool.http-status-lookup.use":"코드를 입력하세요. 쉬운 설명과 함께 문제가 클라이언트 쪽인지 서버 쪽인지 알려줍니다.","tool.json-to-yaml.name":"JSON to YAML 변환기","tool.json-to-yaml.use":"JSON을 붙여넣으면 엄격한 파서도 받아들이는 YAML이 나옵니다. 인용 처리까지 포함해서요.","tool.ltv-calc.name":"LTV 계산기","tool.ltv-calc.use":"모든 대출기관이 금리를 매기는 기준 숫자. LTV와 CLTV, 그리고 80% 선을 확인하세요.","tool.net-worth-calc.name":"순자산 계산기","tool.net-worth-calc.use":"가진 것 전부에서 갚아야 할 것 전부를 뺀 값. 분기마다 확인하는 정직한 숫자 하나입니다.","tool.paver-calc.name":"보도블록 계산기","tool.paver-calc.use":"바닥 치수와 블록 규격만 넣으면 장수·자갈·모래·비용이 한 번에 나옵니다.","tool.secret-santa-generator.name":"시크릿 산타 추첨기","tool.secret-santa-generator.use":"이름을 붙여넣고 추첨을 누르면 누가 누구에게 선물할지 브라우저가 정합니다. 가입도, 이메일도, 자기 자신 뽑기도 없습니다.","tool.slug-generator.name":"URL 슬러그 생성기","tool.slug-generator.use":"제목을 붙여넣으면 검색엔진도 사람도 읽기 쉬운 주소가 나옵니다.","tool.smoking-cost-calc.name":"흡연 비용 계산기","tool.smoking-cost-calc.use":"하루 한 갑에는 숫자가 붙습니다. 10년치까지 함께 보여드립니다.","tool.stamp-duty-calc.name":"영국 인지세(SDLT) 계산기","tool.stamp-duty-calc.use":"잉글랜드·북아일랜드의 현행 SDLT 구간을 구간별로 보여줘, 세액이 어디서 나왔는지 한눈에 확인할 수 있습니다.","tool.stud-calc.name":"스터드 계산기","tool.stud-calc.use":"벽 길이·간격·코너·개구부만 넣으면 로스율까지 포함한 2x4 총 수량이 나옵니다.","tool.tire-size-calc.name":"타이어 사이즈 계산기","tool.tire-size-calc.use":"225/45R17 과 235/40R18 을 넣어 보세요. 외경 차이와 속도계 오차, 3% 규칙 통과 여부를 보여줍니다.","tool.waist-hip-ratio-calc.name":"허리 엉덩이 비율 계산기","tool.waist-hip-ratio-calc.use":"체중계 숫자보다 지방이 어디에 붙었는지가 중요합니다. 줄자 두 번, 숫자 하나.","tool.attendance-calc.name":"출석률 계산기","tool.attendance-calc.use":"현재 출석률, 남은 여유분, 그리고 정확히 몇 번까지 빠져도 되는지.","tool.cgpa-to-percentage.name":"CGPA 백분율 변환기","tool.cgpa-to-percentage.use":"9.5를 곱하는 건 한 교육청의 규칙일 뿐 만능 공식이 아닙니다. 소속 기관이 공표한 계수를 쓰세요.","tool.download-time-calc.name":"다운로드 시간 계산기","tool.download-time-calc.use":"통신사는 비트로 팔고, 파일은 바이트로 셉니다. 대부분의 오차는 이 8배 차이에서 시작됩니다.","tool.ev-charging-calc.name":"전기차 충전 시간 계산기","tool.ev-charging-calc.use":"배터리 용량, 충전기 출력, 그리고 현실적인 효율 — 충전 시간을 결정하는 세 가지 숫자입니다.","tool.gold-purity-calc.name":"금 순도 계산기","tool.gold-purity-calc.use":"22K는 금 91.67%입니다. 실제로 가진 금이 몇 그램인지 확인하세요.","tool.gratuity-calc.name":"인도 퇴직금(Gratuity) 계산기","tool.gratuity-calc.use":"기본급+DA, 근속연수, 15/26 공식 — 5년 요건과 20락(₹2,000,000) 상한까지 함께 계산합니다.","tool.marks-percentage-calc.name":"성적 백분율 계산기","tool.marks-percentage-calc.use":"과목별 점수와 만점을 입력하세요. 전체 백분율(소수점 둘째 자리), 과목별 내역, 등급대를 계산합니다.","tool.nap-calc.name":"낮잠 계산기","tool.nap-calc.use":"20분은 개운하고 60분은 더 피곤합니다. 지금 누우면 몇 시에 알람을 맞춰야 하는지 알려드립니다.","tool.ppi-calc.name":"PPI 계산기","tool.ppi-calc.use":"해상도와 화면 크기를 입력하세요. 픽셀 밀도와 도트 피치, 픽셀이 눈에 보이지 않게 되는 시청 거리를 알려드립니다.","tool.sip-calc.name":"SIP 계산기","tool.sip-calc.use":"매월 적립한 펀드가 만기에 얼마가 되는지, 그중 얼마가 복리로 불어난 몫인지 확인하세요.","tool.torque-conv.name":"토크 변환기","tool.torque-conv.use":"렌치를 맞추기 전에, 한 번 입력으로 네 가지 토크 단위를 확인하세요.","tool.wedding-budget-calc.name":"결혼식 예산 계산기","tool.wedding-budget-calc.use":"총액과 하객 수만 넣으면 플래너가 쓰는 항목별 배분표가 나옵니다.","tool.cholesterol-ratio-calc.name":"콜레스테롤 비율 계산기","tool.cholesterol-ratio-calc.use":"검사지 한 장, 숫자 네 개. 비율은 HDL을 다시 계산에 넣어 줍니다 — 모두 낮을수록 좋습니다.","tool.coffee-ratio-calc.name":"커피 물 비율 계산기","tool.coffee-ratio-calc.use":"물의 양을 넣으면 원두량이, 원두량을 넣으면 물의 양이 추출법별로 나옵니다.","tool.hra-calc.name":"HRA 면세액 계산기","tool.hra-calc.use":"면세액은 세 한도 중 가장 작은 값입니다. 어떤 한도가 걸리는지 보여줍니다.","tool.ppf-calc.name":"PPF 계산기","tool.ppf-calc.use":"15년, 전 단계 비과세. 매년 넣는 돈이 실제로 얼마가 되는지 확인하세요.","tool.px-to-rem.name":"px rem 변환기","tool.px-to-rem.use":"픽셀 값을 입력하면 rem과 붙여넣을 CSS 한 줄이 바로 나옵니다.","tool.rd-calc.name":"정기적금 만기 계산기","tool.rd-calc.use":"회차마다 굴러가는 기간이 다릅니다. 이 계산기는 납입 건별로 하나씩 더합니다.","tool.rent-split-calc.name":"월세 분담 계산기","tool.rent-split-calc.use":"방 크기도 소득도 제각각 — 계약서에 서명하기 전에 누가 얼마를 낼지 정하세요.","tool.robots-txt-generator.name":"robots.txt 생성기","tool.robots-txt-generator.use":"흔한 경우는 프리셋으로, 나머지는 커스텀 규칙으로. 업로드 전에 유효성까지 점검합니다.","tool.salary-hike-calc.name":"연봉 인상률 계산기","tool.salary-hike-calc.use":"양방향 계산: 두 연봉으로 인상률을, 또는 인상률로 인상 후 연봉을 구합니다.","tool.sod-calc.name":"잔디 뗏장 계산기","tool.sod-calc.use":"한 번 재고, 재단 손실을 더해, 처음부터 정확한 롤·팔레트 수량을 주문하세요.","tool.sunrise-sunset-calc.name":"일출 일몰 계산기","tool.sunrise-sunset-calc.use":"NOAA 태양 위치 알고리즘으로 지구 어디든 — 일출·일몰·박명·낮 길이를 브라우저에서 바로 계산합니다.","tool.word-frequency-counter.name":"단어 빈도 계산기","tool.word-frequency-counter.use":"글을 붙여넣으면 실제로 어떤 단어에 기대고 있는지 밀도(%)까지 바로 보입니다.","tool.asphalt-calc.name":"아스팔트 계산기","tool.asphalt-calc.use":"아스팔트가 얼마나 필요한가? 길이·폭·다짐 두께로 톤수, 부피, 자재비를 구합니다.","tool.brick-calc.name":"벽돌 수량 계산기","tool.brick-calc.use":"벽 치수를 넣으면 벽돌 장수가 나옵니다. 대부분의 견적이 빠뜨리는 줄눈과 로스율까지 반영합니다.","tool.car-affordability-calc.name":"자동차 구매 예산 계산기","tool.car-affordability-calc.use":"대출 상담 전에 스스로 정하는 숫자 — 세 가지 규칙을 나란히 비교합니다.","tool.cd-calc.name":"CD 계산기","tool.cd-calc.use":"CD는 APY로 고시되므로 복리가 이미 이율에 들어 있습니다. 그게 금액으로 얼마인지 보여줍니다.","tool.decking-calc.name":"데크 계산기","tool.decking-calc.use":"데크 치수를 넣으면 보드 수량이 나옵니다. 간격·손실률·부자재까지 주문서에 필요한 숫자 그대로.","tool.generator-size-calc.name":"발전기 용량 계산기","tool.generator-size-calc.use":"계속 돌려야 할 것만 체크하세요. 상시 전력을 더한 뒤 가장 크게 기동하는 모터 하나를 얹습니다.","tool.lbm-calc.name":"제지방량 계산기","tool.lbm-calc.use":"지방을 뺀 나머지 전부. 공인된 세 공식과 체지방률 직접 계산법.","tool.rebar-calc.name":"철근 계산기","tool.rebar-calc.use":"슬래브 크기와 배근 간격만 넣으면 그리드 구성·총 연장·주문할 철근 개수가 나옵니다.","tool.refinance-calc.name":"재융자 계산기","tool.refinance-calc.use":"월 납입액이 줄었다고 총비용이 준 것은 아닙니다. 손익분기 시점과 총 이자를 나란히 봅니다.","tool.shingle-calc.name":"지붕 슁글 계산기","tool.shingle-calc.use":"바닥 치수·지붕 경사·여유율이 번들, 스퀘어, 방수시트, 못 수량으로 바뀝니다.","tool.solar-panel-calc.name":"태양광 패널 계산기","tool.solar-panel-calc.use":"고지서의 kWh, 우리 지역 일조시간, 지붕 면적 — 패널 수량을 한 번에.","tool.vo2max-calc.name":"VO2max 계산기","tool.vo2max-calc.use":"세 가지 현장 테스트, 하나의 유산소 한계치 — 내 수치가 어디쯤인지 솔직하게.","tool.annuity-calc.name":"연금 계산기","tool.annuity-calc.use":"질문은 셋, 공식은 하나. 매달 얼마인지, 얼마나 버티는지, 얼마가 필요한지.","tool.ascii-table.name":"ASCII 코드표","tool.ascii-table.use":"문자나 코드를 입력하면 모든 표기를 한 번에. 아래에 0~127 전체 표가 있습니다.","tool.budget-calc.name":"50/30/20 예산 계산기","tool.budget-calc.use":"숫자 하나만 넣으면 이번 달 필수·여유·저축 몫이 바로 나옵니다.","tool.freelance-rate-calc.name":"프리랜서 단가 계산기","tool.freelance-rate-calc.use":"이 금액보다 싸게 받으면, 내 돈 내고 일하는 셈입니다.","tool.meeting-cost-calc.name":"회의 비용 계산기","tool.meeting-cost-calc.use":"모든 회의 초대는 구매 발주서입니다. 보내기 전에 가격표를 확인하세요.","tool.plant-spacing-calc.name":"식재 간격 계산기","tool.plant-spacing-calc.use":"화단 크기와 라벨의 간격만 넣으면, 사기 전에 필요한 모종 수를 알 수 있습니다.","tool.prorated-rent-calc.name":"일할 월세 계산기","tool.prorated-rent-calc.use":"월 중간에 입주하시나요? 정확한 청구액과 세 가지 계산 방식의 차이를 확인하세요.","tool.race-time-predictor.name":"레이스 기록 예측기","tool.race-time-predictor.use":"최근 레이스 하나를 다른 거리의 현실적인 완주 시간으로 바꿉니다.","tool.tv-size-calc.name":"TV 크기 계산기","tool.tv-size-calc.use":"화면 크기는 결국 시야각 문제입니다. 소파까지 거리만 넣으면 나머지는 계산됩니다.","tool.url-parser.name":"URL 파서","tool.url-parser.use":"링크는 필드가 있는 작은 레코드입니다. 붙여넣고 필드를 전부 확인하세요.","tool.cap-rate-calc.name":"Cap Rate 계산기","tool.cap-rate-calc.use":"캡레이트는 대출을 뺀 부동산 자체의 수익률입니다 — 가격, 임대료, 실제 운영비만 봅니다.","tool.carpet-calc.name":"카펫 계산기","tool.carpet-calc.use":"카펫은 방 모양이 아니라 롤에서 잘라 씁니다. 롤 폭이 이음매와 손실의 대부분을 결정합니다.","tool.emergency-fund-calc.name":"비상금 계산기","tool.emergency-fund-calc.use":"3개월인가 6개월인가. 안전망은 세전 소득이 아니라 필수 생활비 기준으로 잡습니다.","tool.furnace-size-calc.name":"퍼니스 용량 계산기","tool.furnace-size-calc.use":"면적만으로는 답이 나오지 않습니다. 기후대 하나로 필요 용량이 거의 두 배가 됩니다.","tool.laminate-flooring-calc.name":"라미네이트 바닥재 계산기","tool.laminate-flooring-calc.use":"방 치수와 박스 라벨에 적힌 시공 면적만 넣으면 사야 할 박스 수가 나옵니다.","tool.matrix-calc.name":"행렬 계산기","tool.matrix-calc.use":"연산 여섯 가지, 크기 두 가지, 그리고 답이 아니라 과정까지.","tool.npv-irr-calc.name":"NPV IRR 계산기","tool.npv-irr-calc.use":"프로젝트 현금흐름을 넣으면 목표수익률 기준으로 실제 가치를 만드는지 바로 보입니다.","tool.party-drink-calc.name":"파티 주류 계산기","tool.party-drink-calc.use":"첫 한 시간에 두 잔, 이후 매시 한 잔 — 인원 수에 맞춰 환산합니다.","tool.permutation-combination-calc.name":"조합·순열 계산기","tool.permutation-combination-calc.use":"순서가 중요한가요? 그 질문에 답하면 나머지는 계산일 뿐입니다.","tool.retaining-wall-calc.name":"옹벽 블록 계산기","tool.retaining-wall-calc.use":"블록 수량, 땅에 묻히는 첫 단, 그리고 10년 뒤 벽이 서 있을지를 결정하는 배수 자갈까지 계산합니다.","tool.water-heater-size-calc.name":"온수기 용량 계산기","tool.water-heater-size-calc.use":"감이 아니라 가장 바쁜 한 시간으로 정합니다 — 탱크 갤런 또는 순간식 GPM.","tool.z-score-calc.name":"Z점수 계산기","tool.z-score-calc.use":"평균에서 표준편차 몇 개만큼 떨어져 있는지, 그래서 백분위 몇 등인지.","tool.army-body-fat-calc.name":"미 육군 체지방 계산기","tool.army-body-fat-calc.use":"배꼽 높이 둘레 한 번과 키만으로, 연령대별 AR 600-9 기준과 대조합니다.","tool.commission-calc.name":"판매 수수료 계산기","tool.commission-calc.use":"같은 거래, 세 가지 수수료 구조 — 실제 지급액을 확인하세요.","tool.commute-cost-calc.name":"통근 비용 계산기","tool.commute-cost-calc.use":"기름값은 청구서의 작은 조각입니다. 감가상각·보험·주차가 나머지입니다.","tool.insulation-calc.name":"단열재 계산기","tool.insulation-calc.use":"목표 R값을 넣으면 두께와 자재 수량이 나옵니다 — 다락, 벽, 바닥 모두.","tool.markdown-table-generator.name":"마크다운 표 생성기","tool.markdown-table-generator.use":"표에 입력하고 파이프를 복사하세요. 정렬 콜론과 여백은 자동으로 처리합니다.","tool.percent-error-calc.name":"퍼센트 오차 계산기","tool.percent-error-calc.use":"내 측정값이 참값에서 얼마나 벗어났는지 — 백분율과 방향으로 확인합니다.","tool.position-size-calc.name":"포지션 사이즈 계산기","tool.position-size-calc.use":"손절가가 주당 리스크를 정하고, 계좌 규모가 감당할 수 있는 오차의 크기를 정합니다.","tool.recipe-scaler.name":"레시피 인분 계산기","tool.recipe-scaler.use":"반으로 줄이거나 두 배로, 7인분에 맞추기까지 — 분수 계산은 도구가 합니다.","tool.siding-calc.name":"사이딩 계산기","tool.siding-calc.use":"둘레·벽 높이·박공만 넣으면 스퀘어와 박스, 트림 길이가 나옵니다.","tool.wilks-calc.name":"윌크스 계산기","tool.wilks-calc.use":"같은 토탈, 두 가지 계수 점수 — 요즘 대부분의 연맹은 DOTS로 순위를 매깁니다.","tool.biweekly-mortgage-calc.name":"격주 상환 모기지 계산기","tool.biweekly-mortgage-calc.use":"2주마다 반씩 내면 1년에 13번 낸 셈이 됩니다. 그 13번째 납입이 실제로 무엇을 벌어주는지 확인하세요.","tool.caffeine-calc.name":"카페인 계산기","tool.caffeine-calc.use":"오늘 마신 카페인을 합산해 400mg 한도와 비교하고, 잠자리에 들 때 남아 있는 양을 확인하세요.","tool.dilution-calc.name":"희석 계산기","tool.dilution-calc.use":"원액 부피, 넣을 희석액, 희석 배수까지 — 실험 노트에 적는 문장 그대로 레시피로 보여줍니다.","tool.grout-calc.name":"줄눈 계산기","tool.grout-calc.use":"타일 크기와 줄눈 폭이 전부를 좌우합니다. 작은 타일은 그라우트를 6배까지 먹습니다.","tool.kinetic-energy-calc.name":"운동에너지 계산기","tool.kinetic-energy-calc.use":"속도가 2배면 에너지는 4배 — 제동거리 이야기의 전부가 여기에 있습니다.","tool.mileage-reimbursement-calc.name":"마일리지 정산 계산기","tool.mileage-reimbursement-calc.use":"주행거리를 넣고 요율을 고르면 경비 보고서에 그대로 쓸 숫자가 나옵니다.","tool.propane-calc.name":"프로판 가스통 계산기","tool.propane-calc.use":"20파운드 가스통 한 통은 약 430,000 BTU. 그 에너지가 얼마나 빨리 사라지는지는 버너가 결정합니다.","tool.ramp-calc.name":"휠체어 경사로 계산기","tool.ramp-calc.use":"높이를 입력하세요. 경사로 길이, 각도, 참 개수, 핸드레일 규정을 알려드립니다.","tool.self-employment-tax-calc.name":"자영업세(SE tax) 계산기","tool.self-employment-tax-calc.use":"프리랜서 소득은 두 번 과세됩니다. 자영업세가 먼저, 소득세가 그 위에. 여기서는 자영업세를 계산합니다.","tool.wavelength-calc.name":"파장 계산기","tool.wavelength-calc.use":"값 하나만 넣으면 파장·주파수·광자 에너지와 스펙트럼상의 위치까지 한 번에 나옵니다.","cat.science":"수학·과학","ux.share":"이 도구 공유","ux.example":"예시로 채우기","ux.copyHint":"탭하여 복사","ux.copied":"복사됨","tools.recent":"최근 사용","sources.heading":"출처·더 읽을거리"};
